INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d84c29ca-1ed2-5aa2-b86c-f1408d07b213','a0000000-0000-4000-8000-0000000000a2','Блок 1. The Verb "to be"',1,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f5b90e17-57d7-5cf2-b4fb-93cf435c8b03','d84c29ca-1ed2-5aa2-b86c-f1408d07b213','The Verb "to be"',0,'LESSON',70,$j$[{"type": "rule", "text": "We normally use the long form of the verb to be (am, is, are) when we write, and the short form ('m, 's, 're) when we speak."}, {"type": "examples", "items": ["Chen is from China and he is fifteen years old.", "'What's the capital city of France?' 'It's Paris.'"]}, {"type": "rule", "text": "In short answers we do not repeat the whole question. We use Yes or No, the subject pronoun and the verb form (am/'m not, is/isn't, are/aren't)."}, {"type": "rule", "text": "We use the long form in positive short answers (Yes, she is.) and the short form in negative short answers (No, I'm not.)."}, {"type": "examples", "items": ["I am not / I'm not", "you are not / you aren't", "he is not / he isn't", "we are not / we aren't", "they are not / they aren't"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d0646692-1a2c-5485-8c6b-90e18e1cb54b','f5b90e17-57d7-5cf2-b4fb-93cf435c8b03',0,'FILL_BLANK','Вставьте правильную (длинную) форму глагола to be.',$j${"items": [{"before": "He ", "after": " a doctor."}, {"before": "We ", "after": " from Spain."}, {"before": "It ", "after": " a telephone."}, {"before": "They ", "after": " sisters."}, {"before": "I ", "after": " not tall."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d0646692-1a2c-5485-8c6b-90e18e1cb54b',$j${"items": [{"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["am"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('282135bb-5c0a-5553-abe2-e9ae67110c89','f5b90e17-57d7-5cf2-b4fb-93cf435c8b03',1,'FILL_BLANK','Заполните пропуски правильной формой глагола to be.',$j${"items": [{"before": "Yes, I ", "after": "."}, {"before": "What ", "after": " your names?"}, {"before": "I ", "after": " Marie and this is Pierre."}, {"before": "", "after": " you from Spain, Carlos?"}, {"before": "No, I ", "after": " from Brazil."}, {"before": "Where ", "after": " you from?"}, {"before": "We ", "after": " from France."}]}$j$::jsonb,10);
