INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('490b89c0-277a-550e-b687-daed35dc7a1f','a0000000-0000-4000-8000-0000000000a2','Блок 2. Question Words',2,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1212db50-551f-5872-86af-6e985bc55a9d','490b89c0-277a-550e-b687-daed35dc7a1f','Question Words',0,'LESSON',70,$j$[{"type": "rule", "text": "We use question words to ask about people, places, things, etc."}, {"type": "examples", "items": ["People: who / whose — Who is Jason? Whose pen is this?", "Things: what / which — What is that? Which hat is yours?", "Place: where — Where is Pete?", "Time: when / how long / how often / what time", "Size: how long / how tall", "Quantity: how much  |  Number: how many", "Manner: how  |  Reason: why  |  Age: how old  |  Distance: how far"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e7175fa4-1a25-590e-a5c2-c6e62b8045fe','1212db50-551f-5872-86af-6e985bc55a9d',0,'CHOOSE','Выберите правильное вопросительное слово.',$j${"items": [{"before": "", "after": " is it? — It's a pen.", "options": [{"id": "o1", "label": "What"}, {"id": "o2", "label": "Which"}]}, {"before": "", "after": " is the black car? — John's.", "options": [{"id": "o1", "label": "Who"}, {"id": "o2", "label": "Whose"}]}, {"before": "", "after": " is Sparky? — He's under the bed.", "options": [{"id": "o1", "label": "Where"}, {"id": "o2", "label": "What"}]}, {"before": "", "after": " is William? — He's 1.70 m.", "options": [{"id": "o1", "label": "How old"}, {"id": "o2", "label": "How tall"}]}, {"before": "", "after": " biscuits are in the box? — Four.", "options": [{"id": "o1", "label": "How much"}, {"id": "o2", "label": "How many"}]}, {"before": "", "after": " is the concert? — Three hours.", "options": [{"id": "o1", "label": "How long"}, {"id": "o2", "label": "How often"}]}, {"before": "", "after": " is Jason? — He's thirteen.", "options": [{"id": "o1", "label": "How old"}, {"id": "o2", "label": "How much"}]}, {"before": "", "after": " book is yours? — The blue one.", "options": [{"id": "o1", "label": "Which"}, {"id": "o2", "label": "What"}]}]}$j$::jsonb,10);
