INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ba04c6a7-244f-5820-b5d7-b6174348bb08','1212db50-551f-5872-86af-6e985bc55a9d',1,'FILL_BLANK','Вставьте нужное вопросительное слово (whose, how far, how many, how much, who, where, how tall, how old).',$j${"items": [{"before": "", "after": " is this magazine? — It's my mother's."}, {"before": "", "after": " is it to the post office? — About ten minutes' walk."}, {"before": "", "after": " brothers have you got? — Three."}, {"before": "", "after": " sugar is there? — One kilo."}, {"before": "", "after": " is that woman? — Mrs Smith."}, {"before": "", "after": " are my glasses? — They're in your bag."}, {"before": "", "after": " is your father? — He's 1.85 metres."}, {"before": "", "after": " is your little sister? — She's four."}]}$j$::jsonb,10);
