INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('34a3467c-4546-5ec9-8e65-c83c9bba5c2d','a0000000-0000-4000-8000-0000000000a2','Блок 3. The Indefinite Article a/an',3,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e4a8fe05-9a1c-5cff-abf7-4fef0795c027','34a3467c-4546-5ec9-8e65-c83c9bba5c2d','The Indefinite Article a/an',0,'LESSON',70,$j$[{"type": "rule", "text": "We use a/an before countable nouns in the singular when we talk about something for the first time or after the verb to be to say what someone or something is."}, {"type": "rule", "text": "We use a before words that begin with a consonant sound and an before words that begin with a vowel sound."}, {"type": "rule", "text": "We don't use a/an before an adjective when there isn't a noun after it. (It's green. It's a green hat.)"}, {"type": "examples", "items": ["a pencil, an orange", "a uniform (consonant sound), an umbrella (vowel sound)", "a helmet (consonant sound), an hour (h is silent)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1fdf7edf-4e1a-5c1b-a435-64c7168b77c4','e4a8fe05-9a1c-5cff-abf7-4fef0795c027',0,'FILL_BLANK','Вставьте a или an.',$j${"items": [{"before": "", "after": " blackboard"}, {"before": "", "after": " accordion"}, {"before": "", "after": " watermelon"}, {"before": "", "after": " owl"}, {"before": "", "after": " egg"}, {"before": "", "after": " tiger"}, {"before": "", "after": " elephant"}, {"before": "", "after": " suitcase"}]}$j$::jsonb,10);
