INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4de31290-afc0-5aab-b902-ff3ba735bf03','a0000000-0000-4000-8000-0000000000a2','Блок 4. The Definite Article the',4,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b117454d-5ca6-56e5-af5a-a8f66bad4061','4de31290-afc0-5aab-b902-ff3ba735bf03','The Definite Article the',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the with nouns that are specific or unique, with rivers, seas, oceans, deserts and mountain ranges, with musical instruments, with morning/afternoon/evening, with cinema/theatre/radio, with nationality words and family names."}, {"type": "rule", "text": "We don't use the with uncountable and plural nouns in general, before proper names, countries, cities, mountains, islands, lakes and continents, before meals and games/sports, before television, or with this/that/these/those and possessives."}, {"type": "examples", "items": ["the Colosseum, the Amazon, the Pacific, the Rocky Mountains", "in the morning, at the cinema, the piano", "Spain, Everest, Malta, Europe, lunch, tennis, television"]}]$j$::jsonb);
