INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3d69ee65-1d7d-573c-8ecd-35bae74cf2ed','a0000000-0000-4000-8000-0000000000a2','Блок 5. Plurals',5,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4216c0ee-66df-590f-b49b-a906e401597a','3d69ee65-1d7d-573c-8ecd-35bae74cf2ed','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns take -s to form the plural (hat → hats). Nouns ending in -s, -ss, -sh, -ch, -x, -o take -es (bus → buses, box → boxes, potato → potatoes)."}, {"type": "rule", "text": "Nouns ending in a vowel + y take -s (key → keys). Nouns ending in a consonant + y drop the -y and take -ies (lady → ladies)."}, {"type": "rule", "text": "Nouns ending in -f or -fe drop the -f/-fe and take -ves (leaf → leaves, knife → knives)."}, {"type": "examples", "items": ["Irregular: child → children, foot → feet, man → men, mouse → mice", "person → people, tooth → teeth, woman → women", "deer → deer, fish → fish, sheep → sheep"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f4d75b23-e870-525e-adf4-d198480b67d6','4216c0ee-66df-590f-b49b-a906e401597a',0,'FILL_BLANK','Напишите форму множественного числа.',$j${"items": [{"before": "duck → ", "after": ""}, {"before": "man → ", "after": ""}, {"before": "knife → ", "after": ""}, {"before": "country → ", "after": ""}, {"before": "person → ", "after": ""}, {"before": "foot → ", "after": ""}, {"before": "glass → ", "after": ""}, {"before": "fox → ", "after": ""}, {"before": "cherry → ", "after": ""}, {"before": "leaf → ", "after": ""}]}$j$::jsonb,10);
