INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c2ecc3e6-0e61-59b6-b947-f0c3f69b547d','460127f1-26f9-55b4-aedc-6c0226b62d67','This / These / That / Those',0,'LESSON',70,$j$[{"type": "rule", "text": "We use this (singular) / these (plural) to refer to people, things and animals near to us."}, {"type": "rule", "text": "We use that (singular) / those (plural) to refer to people, things or animals far away from us."}, {"type": "rule", "text": "We can use this/these and that/those in questions and answer them with it or they."}, {"type": "examples", "items": ["This is a flower. These are flowers.", "That is a balloon. Those are balloons.", "What's this/that? It's a camera.", "What are these/those? They are cameras."]}]$j$::jsonb);
