INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('78edd56f-9efc-501b-a751-1d0a8bbaebb5','a0000000-0000-4000-8000-0000000000a2','Блок 7. Pronouns and Possessives',7,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2981647d-834f-5c81-b274-83de76f5c11a','78edd56f-9efc-501b-a751-1d0a8bbaebb5','Pronouns and Possessives',0,'LESSON',70,$j$[{"type": "rule", "text": "Personal subject pronouns (I, you, he, she, it, we, they) come before verbs instead of nouns or names."}, {"type": "rule", "text": "We use object pronouns (me, you, him, her, it, us, them) after a verb or a preposition."}, {"type": "rule", "text": "Possessive adjectives (my, your, his, her, its, our, their) come before nouns and show possession or relationship."}, {"type": "rule", "text": "Possessive pronouns (mine, yours, his, hers, ours, theirs) come after the verb. There is no possessive pronoun for 'it'."}, {"type": "examples", "items": ["Look at him!", "This is my car.", "That is their bike. → That bike is theirs."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('28e88fd3-93c1-5c37-95cc-ae70a44a8e5a','2981647d-834f-5c81-b274-83de76f5c11a',0,'FILL_BLANK','Вставьте правильное личное или объектное местоимение.',$j${"items": [{"before": "Help ", "after": "! I can't open the window."}, {"before": "This is Emma. ", "after": " is thirteen."}, {"before": "Ask ", "after": ". She can help you."}, {"before": "This is Wendy and Alison. ", "after": " are my sisters."}, {"before": "Look at ", "after": ". They are very tall."}, {"before": "This is my hat. ", "after": " is blue."}, {"before": "Give this to ", "after": ". It's his."}, {"before": "This is Tom. ", "after": " is my brother."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('28e88fd3-93c1-5c37-95cc-ae70a44a8e5a',$j${"items": [{"accept": ["me"]}, {"accept": ["She"]}, {"accept": ["her"]}, {"accept": ["They"]}, {"accept": ["them"]}, {"accept": ["It"]}, {"accept": ["him"]}, {"accept": ["He"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('303d9732-a66e-5154-a39b-5b7ab1c174d0','2981647d-834f-5c81-b274-83de76f5c11a',1,'FILL_BLANK','Вставьте правильное притяжательное местоимение (адъектив/местоимение).',$j${"items": [{"before": "This is a picture of me and my family. ", "after": " house is in London. (наш)"}, {"before": "This is my sister. ", "after": " name is Linda. (её)"}, {"before": "Linda is a big music fan and ", "after": " favourite band is Green Day. (её)"}, {"before": "I've got twin brothers. ", "after": " names are Paul and Mark. (их)"}, {"before": "We've got a dog. His ", "after": " is Spot. (кличка — name)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('303d9732-a66e-5154-a39b-5b7ab1c174d0',$j${"items": [{"accept": ["Our"]}, {"accept": ["Her"]}, {"accept": ["her"]}, {"accept": ["Their"]}, {"accept": ["name"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f0933097-2333-564e-9c32-e2a528b11be8','2981647d-834f-5c81-b274-83de76f5c11a',2,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "This is Mr Jones. He is ", "after": " teacher.", "options": [{"id": "o1", "label": "our"}, {"id": "o2", "label": "ours"}]}, {"before": "I've got a new car. It's ", "after": ".", "options": [{"id": "o1", "label": "my"}, {"id": "o2", "label": "mine"}]}, {"before": "This is Felix and Tiger. ", "after": " are my cats.", "options": [{"id": "o1", "label": "They"}, {"id": "o2", "label": "Them"}]}, {"before": "This is Ben and I'm Harvey. Look at ", "after": ".", "options": [{"id": "o1", "label": "our"}, {"id": "o2", "label": "us"}]}, {"before": "Mary and Helen are my cousins. ", "after": " parents are my aunt and uncle.", "options": [{"id": "o1", "label": "Their"}, {"id": "o2", "label": "Theirs"}]}]}$j$::jsonb,10);
