INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('afc8f422-d0a0-540f-9903-8232963fb14c','a0000000-0000-4000-8000-0000000000a2','Блок 8. The Possessive Case',8,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3d72fde3-f4b8-554a-91ed-db03170191cf','afc8f422-d0a0-540f-9903-8232963fb14c','The Possessive Case',0,'LESSON',70,$j$[{"type": "rule", "text": "We add 's to a singular noun to show possession (Steve's shoes). We add ' to a regular plural noun (the girls' rulers)."}, {"type": "rule", "text": "We add 's to the last noun of a phrase to show that something belongs to two or more people (Robert and Anna's car)."}, {"type": "rule", "text": "We add 's to plural irregular nouns (the men's hats, the women's coats)."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('62549804-c26e-5107-bbb0-dd47d85e9867','3d72fde3-f4b8-554a-91ed-db03170191cf',0,'CHOOSE','Выберите правильную форму притяжательного падежа.',$j${"items": [{"before": "My ", "after": " name is John.", "options": [{"id": "o1", "label": "friend's"}, {"id": "o2", "label": "friends'"}]}, {"before": "", "after": " eyes are blue.", "options": [{"id": "o1", "label": "Helens'"}, {"id": "o2", "label": "Helen's"}]}, {"before": "Our ", "after": " names are Rover and Rex.", "options": [{"id": "o1", "label": "dogs'"}, {"id": "o2", "label": "dog's"}]}, {"before": "These are ", "after": " shoes.", "options": [{"id": "o1", "label": "Steve's"}, {"id": "o2", "label": "Steves'"}]}, {"before": "This is the ", "after": " skirt.", "options": [{"id": "o1", "label": "lady's"}, {"id": "o2", "label": "ladies'"}]}, {"before": "That is ", "after": " television.", "options": [{"id": "o1", "label": "John's and Mary"}, {"id": "o2", "label": "John and Mary's"}]}, {"before": "Her ", "after": " names are Ellen and Tina.", "options": [{"id": "o1", "label": "sister's"}, {"id": "o2", "label": "sisters'"}]}, {"before": "My ", "after": " car is new.", "options": [{"id": "o1", "label": "fathers'"}, {"id": "o2", "label": "father's"}]}]}$j$::jsonb,10);
