INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('0063a4bc-9ea6-5435-ab19-62abdb9104fd','a0000000-0000-4000-8000-0000000000a2','Блок 9. There is / There are, Some / Any',9,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3ba44a31-6e89-5675-a5c9-4676c9cd4db3','0063a4bc-9ea6-5435-ab19-62abdb9104fd','There is / There are, Some / Any',0,'LESSON',70,$j$[{"type": "rule", "text": "We use there is to list things in the singular and there are to list things in the plural. There are has no short form."}, {"type": "rule", "text": "In short answers we use Yes, there is/are or No, there isn't/aren't; we do not repeat the whole question."}, {"type": "rule", "text": "We use some in affirmative sentences with plural countable and uncountable nouns; we use any in negative and interrogative sentences."}, {"type": "examples", "items": ["There are three children in the garden.", "There are some grapes in the picture.", "Are there any bananas in the bowl? No, there aren't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a5758288-8424-55d8-a6aa-31741456ada8','3ba44a31-6e89-5675-a5c9-4676c9cd4db3',0,'CHOOSE','Выберите some или any.',$j${"items": [{"before": "There aren't ", "after": " biscuits in the cupboard.", "options": [{"id": "o1", "label": "any"}, {"id": "o2", "label": "some"}]}, {"before": "There is ", "after": " milk in the fridge.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Is there ", "after": " coffee left?", "options": [{"id": "o1", "label": "any"}, {"id": "o2", "label": "some"}]}, {"before": "There is ", "after": " bread on the table.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Are there ", "after": " plants in the living room?", "options": [{"id": "o1", "label": "any"}, {"id": "o2", "label": "some"}]}, {"before": "There isn't ", "after": " soup.", "options": [{"id": "o1", "label": "any"}, {"id": "o2", "label": "some"}]}, {"before": "There are ", "after": " pens on the desk.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a5758288-8424-55d8-a6aa-31741456ada8',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b5404e19-a5c2-5363-8d9e-2dfadf82dc3d','3ba44a31-6e89-5675-a5c9-4676c9cd4db3',1,'FILL_BLANK','Вставьте there is/there isn''t или there are/there aren''t.',$j${"items": [{"before": "", "after": " some pictures on the wall but"}, {"before": "", "after": " any posters."}, {"before": "", "after": " a lamp but"}, {"before": "", "after": " a chair."}, {"before": "", "after": " some curtains but"}, {"before": "", "after": " any mirrors."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b5404e19-a5c2-5363-8d9e-2dfadf82dc3d',$j${"items": [{"accept": ["There are"]}, {"accept": ["there aren't"]}, {"accept": ["There is"]}, {"accept": ["there isn't"]}, {"accept": ["There are"]}, {"accept": ["there aren't"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8baee9b5-a38f-5ff0-8f66-0d01394c450a','3ba44a31-6e89-5675-a5c9-4676c9cd4db3',2,'FILL_BLANK','Дополните диалог: there is/are, there isn''t/aren''t или is/are there.',$j${"items": [{"before": "", "after": " any Chinese restaurants in this neighbourhood?"}, {"before": "No, ", "after": ", but"}, {"before": "", "after": " a very nice Italian restaurant just around the corner."}, {"before": "", "after": " a supermarket nearby?"}, {"before": "No, I'm afraid ", "after": ", but"}, {"before": "", "after": " two small food shops down this street."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8baee9b5-a38f-5ff0-8f66-0d01394c450a',$j${"items": [{"accept": ["Are there"]}, {"accept": ["there aren't"]}, {"accept": ["there is", "there's"]}, {"accept": ["is there"]}, {"accept": ["there isn't"]}, {"accept": ["there are"]}]}$j$::jsonb,'');
INSERT INTO "LessonUnit" (id,"moduleId",title,subtitle,"orderIndex",kind,"passThreshold",intro) VALUES ('3dd9fbe5-f03c-5def-868e-0e7c9d249a2f','0063a4bc-9ea6-5435-ab19-62abdb9104fd','Тест блока: There is / There are, Some / Any','Ответь верно минимум на 70%, чтобы открыть следующий блок',1,'TEST',70,'[]'::jsonb);
