INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4ea4edac-b8bf-511b-9d40-7a41d598e9c9','ed8cb98c-e900-5f29-8845-8d05da23dbf7','Prepositions of Place',0,'LESSON',70,$j$[{"type": "rule", "text": "We use prepositions of place to say where somebody or something is: in, on, under, behind, next to, near, opposite, in front of, between."}, {"type": "rule", "text": "We use IN with names of cities and countries (in Madrid, in Spain)."}]$j$::jsonb);
