INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('efd2123e-9494-59bf-9dc4-a1aa29c41c78','4ea4edac-b8bf-511b-9d40-7a41d598e9c9',1,'CHOOSE','Выберите правильный предлог места.',$j${"items": [{"before": "We use ", "after": " with names of cities and countries.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}]}, {"before": "The book is ", "after": " the table. (на поверхности)", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "under"}]}, {"before": "The ball is ", "after": " the box. (внутри)", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "behind"}]}]}$j$::jsonb,10);
