INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a519becc-0f57-53db-908d-4de958c81213','a0000000-0000-4000-8000-0000000000a2','Блок 11. Prepositions of Time (at / on / in)',11,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8ee48839-2d69-5740-b441-9c38c20fb0db','a519becc-0f57-53db-908d-4de958c81213','Prepositions of Time (at / on / in)',0,'LESSON',70,$j$[{"type": "rule", "text": "AT: the time (at 5 o'clock), holidays (at Christmas, at Easter), and expressions (at the weekend, at night, at noon, at lunchtime)."}, {"type": "rule", "text": "IN: months (in August), seasons (in winter), years (in 1991), centuries (in the 21st century), parts of the day (in the morning), and expressions (in an hour, in a week)."}, {"type": "rule", "text": "ON: days (on Friday), dates (on 7th May 2005), a specific part of a certain day (on Monday evening), adjective + day (on a hot day)."}, {"type": "rule", "text": "We use from ... to and during to show duration. During goes before a noun (He doesn't work during the weekend)."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cc858a2c-8dad-5ae3-aab6-5e441f59d94e','8ee48839-2d69-5740-b441-9c38c20fb0db',0,'FILL_BLANK','Вставьте at, on, in, from, during или to.',$j${"items": [{"before": "It starts ", "after": " 8 o'clock."}, {"before": "It's ", "after": " Friday morning."}, {"before": "I work the morning shift ", "after": " 8 to 4."}, {"before": "I don't work ", "after": " the weekend."}, {"before": "Can you be here at 7 o'clock ", "after": " the morning?"}, {"before": "My parents got married ", "after": " 24th August, 1988."}, {"before": "Is your birthday ", "after": " June?"}, {"before": "Yes, it's ", "after": " 3rd June."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cc858a2c-8dad-5ae3-aab6-5e441f59d94e',$j${"items": [{"accept": ["at"]}, {"accept": ["on"]}, {"accept": ["from"]}, {"accept": ["at"]}, {"accept": ["in"]}, {"accept": ["on"]}, {"accept": ["in"]}, {"accept": ["on"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3d6321e5-d8b5-5e1b-9803-6f33d4c3795b','8ee48839-2d69-5740-b441-9c38c20fb0db',1,'FILL_BLANK','Вставьте правильный предлог времени (at, on, in).',$j${"items": [{"before": "What are you doing ", "after": " the moment?"}, {"before": "What time do you go to school ", "after": " the morning?"}, {"before": "What time do you go to sleep ", "after": " night?"}, {"before": "What do you do ", "after": " the summer holidays?"}, {"before": "What do you do ", "after": " the weekends?"}, {"before": "What sports do you do ", "after": " winter?"}, {"before": "What do you do ", "after": " a cold day?"}, {"before": "Where were you ", "after": " 5 o'clock yesterday?"}, {"before": "What do you do ", "after": " New Year's Day?"}, {"before": "How old were you ", "after": " 2001?"}]}$j$::jsonb,10);
