INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('94abefb2-e906-5596-93c2-dbe327aaaf0e','d46702b2-4807-5cc4-8015-9a74df70e1e2','Prepositions of Movement',0,'LESSON',70,$j$[{"type": "rule", "text": "We use prepositions of movement to show the direction in which someone or something is moving: along, across, up, down, into, out of, over, through."}, {"type": "rule", "text": "We use by + car/bus/train/taxi/plane/boat, BUT on foot."}, {"type": "rule", "text": "When there is an article, a possessive adjective or the possessive case before the means of transport, we don't use by (in my car, on the bus, in a taxi)."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9361e5b1-3380-58aa-8c55-d7320594771d','94abefb2-e906-5596-93c2-dbe327aaaf0e',0,'FILL_BLANK','Вставьте правильный предлог движения.',$j${"items": [{"before": "Get ", "after": " the car and I'll give you a lift. (внутрь)"}, {"before": "Wait for the lollipop lady to take you ", "after": " the road. (через)"}, {"before": "Climb ", "after": " from that tree right now! (вниз)"}, {"before": "I saw Jane coming ", "after": " the post office. (из)"}, {"before": "She got ", "after": " her car and drove away. (внутрь)"}]}$j$::jsonb,10);
