INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4b8b1f11-cf57-5b23-a4e6-6d8c9c17b1cc','a0000000-0000-4000-8000-0000000000a2','Блок 13. Have got',13,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c','4b8b1f11-cf57-5b23-a4e6-6d8c9c17b1cc','Have got',0,'LESSON',70,$j$[{"type": "rule", "text": "We use have got to show that something belongs to somebody, to talk about relationships and to describe the characteristics of people, animals or things."}, {"type": "rule", "text": "Short forms: I've/you've/we've/they've got, he's/she's/it's got. Negatives: haven't got, hasn't got."}, {"type": "rule", "text": "In short answers we do not use got: Yes, I have. / No, he hasn't."}, {"type": "examples", "items": ["Paul has got a motorbike.", "Karen has got long blonde hair and blue eyes.", "He's a singer. (He is)  |  He's got a brother. (He has)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3500c592-2083-599d-846e-38ec1c82dc49','42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c',0,'FILL_BLANK','Вставьте have, haven''t, has или hasn''t.',$j${"items": [{"before": "Has Mary got long hair? No, she ", "after": "."}, {"before": "We ", "after": " got a dog. We have got a cat."}, {"before": "", "after": " you got a sister? Yes, I have."}, {"before": "Have they got a car? No, they ", "after": "."}, {"before": "We ", "after": " got a big house. We've got a small one."}, {"before": "", "after": " your grandfather got a moustache? Yes, he has."}, {"before": "I ", "after": " got brown hair. I've got blonde hair."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3500c592-2083-599d-846e-38ec1c82dc49',$j${"items": [{"accept": ["hasn't"]}, {"accept": ["haven't"]}, {"accept": ["Have"]}, {"accept": ["haven't"]}, {"accept": ["haven't"]}, {"accept": ["Has"]}, {"accept": ["haven't"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('89248f0d-af0e-5adf-adda-3f496db373b5','42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c',1,'FILL_BLANK','Вставьте ''s, hasn''t, ''ve или haven''t.',$j${"items": [{"before": "Michael ", "after": " got a guitar."}, {"before": "I ", "after": " got a skateboard and a bike."}, {"before": "She ", "after": " got a piano (у неё нет)."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('89248f0d-af0e-5adf-adda-3f496db373b5',$j${"items": [{"accept": ["'s"]}, {"accept": ["'ve"]}, {"accept": ["hasn't"]}]}$j$::jsonb,'');
INSERT INTO "LessonUnit" (id,"moduleId",title,subtitle,"orderIndex",kind,"passThreshold",intro) VALUES ('0dd3ae07-36c2-570e-acc0-b87e42ac2348','4b8b1f11-cf57-5b23-a4e6-6d8c9c17b1cc','Тест блока: Have got','Ответь верно минимум на 70%, чтобы открыть следующий блок',1,'TEST',70,'[]'::jsonb);
