INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('30caa025-a2d4-5a6a-90c9-2d4416bf5d90','a0000000-0000-4000-8000-0000000000a2','Блок 14. Present Simple',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('98369d51-e207-5e18-b010-21a30501b2c2','30caa025-a2d4-5a6a-90c9-2d4416bf5d90','Present Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "Most verbs take -s in the third person singular (he forgets, she climbs). Verbs ending in -ss, -sh, -ch, -x or -o take -es (misses, pushes, catches, fixes, does)."}, {"type": "rule", "text": "Verbs ending in a consonant + y drop the -y and take -ies (cry → cries). Verbs ending in a vowel + y take -s only (buy → buys)."}, {"type": "rule", "text": "We use the present simple for daily routines, habits, permanent states and general truths or laws of nature."}, {"type": "examples", "items": ["He catches the school bus at 7:30 every morning.", "Matt lives in London. He sells cars.", "The sun sets in the west."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('504839aa-2466-537b-a8a1-19de55379937','98369d51-e207-5e18-b010-21a30501b2c2',0,'FILL_BLANK','Напишите форму 3-го лица единственного числа.',$j${"items": [{"before": "play → ", "after": ""}, {"before": "mix → ", "after": ""}, {"before": "match → ", "after": ""}, {"before": "drink → ", "after": ""}, {"before": "finish → ", "after": ""}, {"before": "kiss → ", "after": ""}, {"before": "pay → ", "after": ""}, {"before": "go → ", "after": ""}, {"before": "wash → ", "after": ""}, {"before": "try → ", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('504839aa-2466-537b-a8a1-19de55379937',$j${"items": [{"accept": ["plays"]}, {"accept": ["mixes"]}, {"accept": ["matches"]}, {"accept": ["drinks"]}, {"accept": ["finishes"]}, {"accept": ["kisses"]}, {"accept": ["pays"]}, {"accept": ["goes"]}, {"accept": ["washes"]}, {"accept": ["tries"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e49818c9-92c4-581b-9802-d2f2252fd36d','98369d51-e207-5e18-b010-21a30501b2c2',1,'FILL_BLANK','Вставьте do, does, don''t или doesn''t.',$j${"items": [{"before": "", "after": " you like learning foreign languages? Yes, I do."}, {"before": "", "after": " you go on holiday to Spain every year? Yes, we do."}, {"before": "Do you do your shopping on Thursdays? No, we ", "after": ". We do it on Saturdays."}, {"before": "Why ", "after": " Chloe look sad? I don't know."}, {"before": "", "after": " they live in York? No, they don't."}, {"before": "Does your father drive to work every day? No, he ", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e49818c9-92c4-581b-9802-d2f2252fd36d',$j${"items": [{"accept": ["Do"]}, {"accept": ["Do"]}, {"accept": ["don't"]}, {"accept": ["does"]}, {"accept": ["Do"]}, {"accept": ["doesn't"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4e5d3844-ea53-5d7f-9552-4ab8c04767c0','98369d51-e207-5e18-b010-21a30501b2c2',2,'FILL_BLANK','Поставьте глагол в present simple (используйте don''t/doesn''t, где нужно).',$j${"items": [{"before": "Water ", "after": " (freeze) at 0°C."}, {"before": "Penguins ", "after": " (live) in the Antarctic."}, {"before": "Orange trees ", "after": " (grow) in the North Pole."}, {"before": "Milk ", "after": " (come) from cows."}, {"before": "The sun ", "after": " (rise) in the west."}, {"before": "Horses ", "after": " (lay) eggs."}, {"before": "The Moon ", "after": " (move) round the Earth."}, {"before": "Rectangles ", "after": " (have) five sides."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4e5d3844-ea53-5d7f-9552-4ab8c04767c0',$j${"items": [{"accept": ["freezes"]}, {"accept": ["live"]}, {"accept": ["don't grow"]}, {"accept": ["comes"]}, {"accept": ["doesn't rise"]}, {"accept": ["don't lay"]}, {"accept": ["moves"]}, {"accept": ["don't have"]}]}$j$::jsonb,'');
