INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('bd52f5e6-dd10-551d-bc43-d8c5ce550940','a0000000-0000-4000-8000-0000000000a2','Блок 15. Adverbs of Frequency',15,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2f691974-0d66-56ce-9253-b9fc54e98fb4','bd52f5e6-dd10-551d-bc43-d8c5ce550940','Adverbs of Frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of frequency show how often something happens: always (100%), usually (75%), often (50%), sometimes (20%), never (0%)."}, {"type": "rule", "text": "We use adverbs of frequency before the main verb but after the verb to be."}, {"type": "examples", "items": ["They often play computer games in the afternoon.", "Ben is sometimes late for school.", "I usually get up at 7 o'clock."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8ddef59c-5597-51ea-9e49-a34086ce32bc','2f691974-0d66-56ce-9253-b9fc54e98fb4',0,'REORDER','Составьте предложение из слов.',$j${"tiles": ["They", "often", "play", "computer games", "in", "the", "afternoon"]}$j$::jsonb,10);
