INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('29b74970-1456-573e-919a-162f94875b0c','a0000000-0000-4000-8000-0000000000a2','Блок 16. Present Simple & Adverbs of Frequency',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d521a697-137b-5ae9-a326-693ced8a763e','29b74970-1456-573e-919a-162f94875b0c','Present Simple & Adverbs of Frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for habits, routines, repeated actions, permanent states and facts."}, {"type": "rule", "text": "We form the negative with don't/doesn't and questions with do/does. In the third person singular the verb takes -s (he lives, she goes)."}, {"type": "rule", "text": "Adverbs of frequency (always, usually, often, sometimes, never) go before the main verb but after the verb 'to be'."}, {"type": "examples", "items": ["Lisa always arrives early.", "She is never late.", "How often does Beatrice go to the supermarket?"]}]$j$::jsonb);
