INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('5da2dd97-894d-52e8-ac84-b8793103800b','a0000000-0000-4000-8000-0000000000a2','Блок 17. Present Continuous',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c935b0f0-b5c2-5f0b-bcd6-1a44cc439b5e','5da2dd97-894d-52e8-ac84-b8793103800b','Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the present continuous with subject + to be (am/is/are) + verb -ing. Negative: I'm not working, he isn't working. Interrogative: Am I working? Are they working?"}, {"type": "rule", "text": "Spelling: verbs ending in -e drop the -e and add -ing (smile - smiling); verbs ending in a vowel + consonant double the consonant (run - running); verbs ending in -ie change -ie to -y (tie - tying)."}, {"type": "rule", "text": "We use the present continuous for actions happening now, temporary situations, and fixed arrangements in the near future."}, {"type": "examples", "items": ["Karen is working on the computer now.", "She is working very hard these days.", "Bob is flying to Madrid in two hours."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('df5b1a99-cdf5-5a57-93a0-cefa064ce8a6','c935b0f0-b5c2-5f0b-bcd6-1a44cc439b5e',0,'FILL_BLANK','Раскройте скобки, поставив глагол в present continuous.',$j${"items": [{"before": "I ", "after": " (not/watch) TV now."}, {"before": "Tom ", "after": " (study) at the library now."}, {"before": "We ", "after": " (stay) with my aunt until we find a flat of our own."}, {"before": "Melinda ", "after": " (not/go) to the party tonight."}, {"before": "Jane and Claire ", "after": " (meet) us this afternoon."}, {"before": "Mum's in the garden. She ", "after": " (water) the plants."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('df5b1a99-cdf5-5a57-93a0-cefa064ce8a6',$j${"items": [{"accept": ["am not watching", "'m not watching"]}, {"accept": ["is studying"]}, {"accept": ["are staying"]}, {"accept": ["is not going", "isn't going"]}, {"accept": ["are meeting"]}, {"accept": ["is watering"]}]}$j$::jsonb,'');
