INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b42f234a-530b-5427-aa68-8cff47f80ec4','a0000000-0000-4000-8000-0000000000a2','Блок 18. Present Simple vs Present Continuous',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8942bc65-ada6-5f2e-a2d7-8ba92a79038a','b42f234a-530b-5427-aa68-8cff47f80ec4','Present Simple vs Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for daily routines, habits, repeated actions, permanent states and facts. Time expressions: every day, usually, always, in the morning."}, {"type": "rule", "text": "We use the present continuous for actions happening now, temporary actions and fixed arrangements in the near future. Time expressions: now, at the moment, these days, tonight."}, {"type": "rule", "text": "Stative verbs (like, love, want, know, need, believe) describe a state, not an action, so they have no continuous form."}, {"type": "examples", "items": ["They play basketball every Saturday.", "The baby is sleeping at the moment.", "I like your new shirt. (NOT: I am liking)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b1d98e40-11fc-567c-ac7d-b9ad2e401df1','8942bc65-ada6-5f2e-a2d7-8ba92a79038a',0,'FILL_BLANK','Раскройте скобки, употребив present simple или present continuous.',$j${"items": [{"before": "The children ", "after": " (play) in the park now."}, {"before": "They often ", "after": " (go) there in the afternoons."}, {"before": "Joe ", "after": " (work) in a hospital."}, {"before": "Cathy ", "after": " (not/drive) a car."}, {"before": "Jim ", "after": " (live) with some friends until he moves into his new flat."}, {"before": "We can go out. It ", "after": " (not/rain) now."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b1d98e40-11fc-567c-ac7d-b9ad2e401df1',$j${"items": [{"accept": ["are playing"]}, {"accept": ["go"]}, {"accept": ["works"]}, {"accept": ["doesn't drive", "does not drive"]}, {"accept": ["is living"]}, {"accept": ["isn't raining", "is not raining"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9c8fdadc-a7c3-59d3-aeef-edcaf48ff64c','8942bc65-ada6-5f2e-a2d7-8ba92a79038a',1,'FILL_BLANK','Раскройте скобки, употребив present simple или present continuous.',$j${"items": [{"before": "Sorry, I can't. I ", "after": " (go) to the cinema with some friends."}, {"before": "No, he ", "after": " (work) on the computer."}, {"before": "Yes. He ", "after": " (work) hard these days."}, {"before": "Yes, I ", "after": " (drink) a cup every afternoon."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9c8fdadc-a7c3-59d3-aeef-edcaf48ff64c',$j${"items": [{"accept": ["am going", "'m going"]}, {"accept": ["is working"]}, {"accept": ["is working"]}, {"accept": ["drink"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('215a7d8e-eae1-5771-935a-5ece4892a2d8','8942bc65-ada6-5f2e-a2d7-8ba92a79038a',2,'CHOOSE','Выберите правильное обстоятельство времени.',$j${"items": [{"before": "George and Jennifer have French lessons ", "after": ".", "options": [{"id": "o1", "label": "on Thursdays"}, {"id": "o2", "label": "at the moment"}]}, {"before": "Bob is going to a concert ", "after": ".", "options": [{"id": "o1", "label": "tonight"}, {"id": "o2", "label": "every Friday"}]}, {"before": "She is living with her cousin ", "after": ".", "options": [{"id": "o1", "label": "at present"}, {"id": "o2", "label": "at nights"}]}, {"before": "I am taking five courses ", "after": ".", "options": [{"id": "o1", "label": "this semester"}, {"id": "o2", "label": "every day"}]}, {"before": "Helen isn't working ", "after": ".", "options": [{"id": "o1", "label": "at the moment"}, {"id": "o2", "label": "on Sundays"}]}]}$j$::jsonb,10);
