INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c249a80e-b43c-5075-9791-11a8df7bbbbd','a0000000-0000-4000-8000-0000000000a2','Блок 19. Present Simple & Present Continuous Revision',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b7dc5218-cf90-53df-a907-30415d2b40e0','c249a80e-b43c-5075-9791-11a8df7bbbbd','Present Simple & Present Continuous Revision',0,'LESSON',70,$j$[{"type": "rule", "text": "The present simple describes permanent states, habits/routines and facts; the present continuous describes actions happening now, temporary situations and fixed arrangements in the near future."}, {"type": "text", "text": "Time expressions signal the tense: 'usually, every day, on Saturdays' go with the present simple, while 'now, at the moment, tonight, this week' go with the present continuous."}, {"type": "examples", "items": ["Fabio lives in Rome but he is visiting his aunt in Naples at the moment.", "This afternoon, we're driving to Mt Vesuvius."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('242e5dc1-3fe2-59d2-bfa9-8463148d4929','b7dc5218-cf90-53df-a907-30415d2b40e0',0,'CHOOSE','Выберите правильное обстоятельство времени.',$j${"items": [{"before": "Martha usually does her food shopping ", "after": ".", "options": [{"id": "o1", "label": "on Saturdays"}, {"id": "o2", "label": "at the moment"}]}, {"before": "It isn't raining ", "after": ".", "options": [{"id": "o1", "label": "now"}, {"id": "o2", "label": "at the weekend"}]}, {"before": "Ron has a piano lesson ", "after": ".", "options": [{"id": "o1", "label": "twice a week"}, {"id": "o2", "label": "these days"}]}, {"before": "Sophie is sitting her exams ", "after": ".", "options": [{"id": "o1", "label": "this week"}, {"id": "o2", "label": "at night"}]}, {"before": "George buys a newspaper ", "after": ".", "options": [{"id": "o1", "label": "every day"}, {"id": "o2", "label": "today"}]}, {"before": "Tom isn't driving to work ", "after": ".", "options": [{"id": "o1", "label": "today"}, {"id": "o2", "label": "every day"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('242e5dc1-3fe2-59d2-bfa9-8463148d4929',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
