INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d766fcab-b886-5dc7-88a0-66fbb22059a6','a0000000-0000-4000-8000-0000000000a2','Блок 20. Past Simple',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('57a7d7f6-fa47-546c-8a8b-6290ee386477','d766fcab-b886-5dc7-88a0-66fbb22059a6','Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "Regular verbs form the past simple with -ed. The negative is didn't + base form and the interrogative is Did + subject + base form for all persons."}, {"type": "rule", "text": "Spelling: verbs ending in -e take only -d (dance - danced); consonant + y drop the -y and take -ied (try - tried); one stressed vowel between two consonants double the consonant (stop - stopped)."}, {"type": "rule", "text": "Irregular verbs do not add -ed (have - had, bring - brought, leave - left). We use the past simple for actions at a particular time in the past."}, {"type": "examples", "items": ["They spent their holidays in Mexico last winter.", "First she answered the phone and then she wrote down the message.", "Elvis Presley sang many great songs."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('391326ca-04db-5ac3-8b53-2baf26b08dd6','57a7d7f6-fa47-546c-8a8b-6290ee386477',0,'FILL_BLANK','Раскройте скобки, поставив глагол в past simple.',$j${"items": [{"before": "The Phantom first ", "after": " (appear) in a newspaper comic strip in 1936."}, {"before": "He soon ", "after": " (become) one of America's most loved superheroes."}, {"before": "The Phantom ", "after": " (live) alone in the jungles of Africa."}, {"before": "He ", "after": " (choose) to become a superhero."}, {"before": "He ", "after": " (want) to help people in danger."}, {"before": "The Phantom ", "after": " (wear) a purple costume."}, {"before": "He ", "after": " (not/have) any super-human abilities."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('391326ca-04db-5ac3-8b53-2baf26b08dd6',$j${"items": [{"accept": ["appeared"]}, {"accept": ["became"]}, {"accept": ["lived"]}, {"accept": ["chose"]}, {"accept": ["wanted"]}, {"accept": ["wore"]}, {"accept": ["didn't have", "did not have"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('aa38a5ce-95ba-5676-aec5-47c503555f15','57a7d7f6-fa47-546c-8a8b-6290ee386477',1,'FILL_BLANK','Раскройте скобки, поставив глагол в past simple.',$j${"items": [{"before": "I ", "after": " (eat) a sandwich."}, {"before": "No, I ", "after": " (not/have) my camera with me."}, {"before": "No, they ", "after": " (stay) in and chatted online with friends."}, {"before": "He ", "after": " (take) a taxi."}]}$j$::jsonb,10);
