INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('22251f73-bed8-5c44-bf69-8e48db1c7ab6','57a7d7f6-fa47-546c-8a8b-6290ee386477',2,'MATCH_PAIRS','Соотнесите вопросы с ответами.',$j${"left": [{"id": "l1", "label": "What time did you wake up this morning?"}, {"id": "l2", "label": "When did he finish university?"}, {"id": "l3", "label": "Why did they go to London?"}, {"id": "l4", "label": "What did you have for breakfast?"}, {"id": "l5", "label": "When did Tom start playing the piano?"}, {"id": "l6", "label": "Who did Emily invite to the barbecue?"}], "right": [{"id": "r1", "label": "At 7 o'clock."}, {"id": "r2", "label": "Two years ago."}, {"id": "r3", "label": "For business."}, {"id": "r4", "label": "Cereal."}, {"id": "r5", "label": "When he was 6."}, {"id": "r6", "label": "Shelly and Robert."}]}$j$::jsonb,10);
