INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('68a56730-111f-58ac-84a2-9db8bb4672dc','a0000000-0000-4000-8000-0000000000a2','Блок 21. Used to',21,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('ce0b2ac1-cc37-563b-a193-16c7d2960184','68a56730-111f-58ac-84a2-9db8bb4672dc','Used to',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'used to' to talk about past habits or things that happened regularly in the past but no longer happen, and for things that were true but are not true any more."}, {"type": "rule", "text": "'Used to' has no present form. The question form is 'Did (you) use to ...?' and the negative is '(I) didn't use to ...'."}, {"type": "rule", "text": "We can use the past simple instead of 'used to' with no difference in meaning for repeated actions, but NOT for a single past action."}, {"type": "examples", "items": ["He used to ride a bicycle when he was young. Now he drives a car.", "She used to have long hair when she was a child.", "Did Anna use to study long hours?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('300da5ba-4c30-5aaa-816f-b363ac5d94ae','ce0b2ac1-cc37-563b-a193-16c7d2960184',0,'MATCH_PAIRS','Соотнесите глагол со словосочетанием (как в примере: have - long hair).',$j${"left": [{"id": "l1", "label": "have"}, {"id": "l2", "label": "live"}, {"id": "l3", "label": "not go"}, {"id": "l4", "label": "not play"}, {"id": "l5", "label": "not eat"}, {"id": "l6", "label": "read"}], "right": [{"id": "r1", "label": "long hair"}, {"id": "r2", "label": "in a big house"}, {"id": "r3", "label": "to bed late"}, {"id": "r4", "label": "computer games"}, {"id": "r5", "label": "fish"}, {"id": "r6", "label": "comic books"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('300da5ba-4c30-5aaa-816f-b363ac5d94ae',$j${"pairs": [{"l": "l1", "r": "r1"}, {"l": "l2", "r": "r2"}, {"l": "l3", "r": "r3"}, {"l": "l4", "r": "r4"}, {"l": "l5", "r": "r5"}, {"l": "l6", "r": "r6"}]}$j$::jsonb,'');
