INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('dff7d04a-e1f0-5c3a-bc86-3130d99ad791','07002e67-37e7-5b91-915f-72bf7365563c','Past Simple & Used to Revision',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the past simple for actions which happened at a specific time in the past and for actions which took place one after the other."}, {"type": "rule", "text": "The negative is didn't + base form, questions are Did + subject + base form, and short answers are 'Yes, I did / No, I didn't'."}, {"type": "examples", "items": ["When he was 13, he won his first film prize.", "First, Steven directed television programmes and then he started to direct films.", "This film made over $470 million dollars at the box office."]}]$j$::jsonb);
