INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a6c3acbd-a3e5-55f6-8e04-1ae5207b6d21','a0000000-0000-4000-8000-0000000000a2','Блок 23. Past Continuous',23,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('bea521cf-7eaa-5261-9c9d-3020a0c5bbc5','a6c3acbd-a3e5-55f6-8e04-1ae5207b6d21','Past Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the past continuous with subject + was/were + verb -ing. I/He/She/It was talking; We/You/They were talking."}, {"type": "rule", "text": "We use it for an action which was in progress at a stated time in the past (we don't know when it started or finished), and for two or more actions happening at the same time (with while)."}, {"type": "rule", "text": "For a past action in progress interrupted by another, we use the past continuous for the longer action and the past simple for the shorter one."}, {"type": "examples", "items": ["Mrs Adams was having dinner at 6 o'clock yesterday evening.", "Claire was writing in her diary when her friend called her.", "Tony was surfing the Net while Anna was reading."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('dcf7c7d9-4f9c-5139-b4ae-622c0875e622','bea521cf-7eaa-5261-9c9d-3020a0c5bbc5',0,'FILL_BLANK','Раскройте скобки, поставив глагол в past continuous.',$j${"items": [{"before": "At 11 o'clock last night, I ", "after": " (sleep)."}, {"before": "Felix ", "after": " (work) at 1:00 yesterday afternoon."}, {"before": "Emma and Claire ", "after": " (have) coffee."}, {"before": "Robert ", "after": " (paint) his house."}, {"before": "Frank and Mary ", "after": " (walk) their dogs."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('dcf7c7d9-4f9c-5139-b4ae-622c0875e622',$j${"items": [{"accept": ["was sleeping"]}, {"accept": ["was working"]}, {"accept": ["were having"]}, {"accept": ["was painting"]}, {"accept": ["were walking"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ee29b31e-6cea-5658-b88d-f12704338481','bea521cf-7eaa-5261-9c9d-3020a0c5bbc5',1,'FILL_BLANK','Раскройте скобки, поставив глагол в past continuous.',$j${"items": [{"before": "Jim and Tom ", "after": " (play) football."}, {"before": "Mrs Jones ", "after": " (talk) on the phone."}, {"before": "Katie and Emma ", "after": " (draw) a picture."}, {"before": "Grandma ", "after": " (wash) the dishes."}]}$j$::jsonb,10);
