INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('755bbcd5-74de-5237-8260-9629c34a75cc','a0000000-0000-4000-8000-0000000000a2','Блок 24. Past Continuous vs Past Simple',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('05230514-e8e5-5ee2-af92-7fadb302c386','755bbcd5-74de-5237-8260-9629c34a75cc','Past Continuous vs Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the past simple for an action completed at a stated time in the past, and for actions which happened immediately one after the other."}, {"type": "rule", "text": "We use the past continuous for an action which was in progress at a stated time in the past (we don't know when it started or finished)."}, {"type": "rule", "text": "When one action interrupts another, the longer action in progress goes in the past continuous and the shorter interrupting action goes in the past simple."}, {"type": "examples", "items": ["James and Alice bought a new house last week.", "Bill was making a cup of coffee when the phone rang."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('73c609f2-dee4-5dee-a4be-6b5aef2c76a5','05230514-e8e5-5ee2-af92-7fadb302c386',0,'FILL_BLANK','Раскройте скобки, употребив past continuous или past simple.',$j${"items": [{"before": "I ", "after": " (play) a computer game when the electricity went out."}, {"before": "Sue was cooking when she ", "after": " (burn) her finger."}, {"before": "They ", "after": " (jog) in the park when a dog attacked them."}, {"before": "The alarm ", "after": " (go off) while we were sleeping heavily."}, {"before": "Daisy ", "after": " (fall) over while she was skating."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('73c609f2-dee4-5dee-a4be-6b5aef2c76a5',$j${"items": [{"accept": ["was playing"]}, {"accept": ["burnt", "burned"]}, {"accept": ["were jogging"]}, {"accept": ["went off"]}, {"accept": ["fell"]}]}$j$::jsonb,'');
