INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('98f7395c-62a5-509a-9a8c-2f69a81466b4','a0000000-0000-4000-8000-0000000000a2','Блок 25. Past Simple & Past Continuous',25,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a93e4575-59ef-5ab3-ac66-a8f144f8b400','98f7395c-62a5-509a-9a8c-2f69a81466b4','Past Simple & Past Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the past continuous for two or more actions which were happening at the same time in the past, and for a past action which was in progress when another action interrupted it."}, {"type": "examples", "items": ["He was reading the newspaper while he was eating a sandwich.", "He was walking to work when he met a friend in the street.", "Tom was studying when Sam called him."]}, {"type": "text", "text": "Time expressions used with the past continuous: while, when, as, all day/night/morning, all day yesterday, etc. The past simple is used for a completed action or for actions which happened one after the other in the past."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('95e3d292-9daf-54e9-87d8-cb9faf857374','a93e4575-59ef-5ab3-ac66-a8f144f8b400',0,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "Last year, we", "after": "to India on holiday.", "options": [{"id": "o1", "label": "travelled"}, {"id": "o2", "label": "were travelling"}]}, {"before": "Claire", "after": "for the bus when she tripped over her shoelaces.", "options": [{"id": "o1", "label": "was running"}, {"id": "o2", "label": "ran"}]}, {"before": "The baby", "after": "at 10 o'clock this morning.", "options": [{"id": "o1", "label": "was sleeping"}, {"id": "o2", "label": "slept"}]}, {"before": "At 5 o'clock yesterday afternoon, David and his brother", "after": "their dog a bath.", "options": [{"id": "o1", "label": "were giving"}, {"id": "o2", "label": "gave"}]}, {"before": "The students", "after": "carefully while the teacher was speaking.", "options": [{"id": "o1", "label": "were listening"}, {"id": "o2", "label": "listened"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('95e3d292-9daf-54e9-87d8-cb9faf857374',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0b12d4fa-8562-5cb7-8e37-b29d0dfedb31','a93e4575-59ef-5ab3-ac66-a8f144f8b400',1,'FILL_BLANK','Поставьте глаголы в скобках в past simple или past continuous.',$j${"items": [{"before": "Last year we", "after": "(travel) to Germany on holiday."}, {"before": "Anna", "after": "(drink) tea at four o'clock yesterday afternoon."}, {"before": "Keith was walking down the street when it", "after": "(start) to snow."}, {"before": "Tom and James", "after": "(walk) by the lake when they saw an old house."}]}$j$::jsonb,10);
