INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('6a5dc2ae-a863-5413-aa42-14c274e7c396','a0000000-0000-4000-8000-0000000000a2','Блок 26. Future Simple (Will)',26,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b3548d25-83f7-5040-9148-b68493c55374','6a5dc2ae-a863-5413-aa42-14c274e7c396','Future Simple (Will)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the future simple with will + bare infinitive. Will is the same for all persons. Questions are formed by putting will before the subject; negations by putting not after will (short form won't)."}, {"type": "text", "text": "We use will: for on-the-spot decisions; with the verbs hope, think, believe, expect; to make predictions based on what we think or imagine; with I'm sure, I'm afraid; with probably, perhaps."}, {"type": "examples", "items": ["He'll go to Greece this summer.", "Will they go on holiday this year?", "Kevin won't like this film.", "I will probably go to Paris."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5c133e2b-31ea-5fec-b987-1554c64842e4','b3548d25-83f7-5040-9148-b68493c55374',0,'FILL_BLANK','Заполните пропуски с will (''ll) или won''t.',$j${"items": [{"before": "You're a fast runner. I'm sure you", "after": "win the race."}, {"before": "I'm afraid that I", "after": "have time to help you study."}, {"before": "The door bell is ringing. I", "after": "answer it."}, {"before": "Tom isn't very popular. He", "after": "win the election."}, {"before": "We haven't got any tomatoes. I", "after": "go and buy some."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5c133e2b-31ea-5fec-b987-1554c64842e4',$j${"items": [{"accept": ["will", "'ll"]}, {"accept": ["won't", "will not"]}, {"accept": ["will", "'ll"]}, {"accept": ["won't", "will not"]}, {"accept": ["will", "'ll"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4ac5d86d-7660-525f-8034-bd70e1b7159a','b3548d25-83f7-5040-9148-b68493c55374',1,'SORT_COLUMNS','Определите тип: предсказание или спонтанное решение.',$j${"columns": [{"id": "c1", "label": "Prediction"}, {"id": "c2", "label": "On-the-spot decision"}], "items": [{"id": "i1", "label": "I expect James will do well in his exams."}, {"id": "i2", "label": "I haven't got any milk. I'll go and buy some."}, {"id": "i3", "label": "Sarah will probably like the red skirt better."}, {"id": "i4", "label": "All cars will be electric in 2060."}, {"id": "i5", "label": "The house is on fire. I will call the fire brigade."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4ac5d86d-7660-525f-8034-bd70e1b7159a',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c1", "i4": "c1", "i5": "c2"}}$j$::jsonb,'');
