INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2269858a-05a4-5627-8ec8-dcf723c305cc','a0000000-0000-4000-8000-0000000000a2','Блок 27. Conditionals - Types 0, 1 & 2',27,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d32ebec1-89b1-50d2-bf14-1755bc656d14','2269858a-05a4-5627-8ec8-dcf723c305cc','Conditionals - Types 0, 1 & 2',0,'LESSON',70,$j$[{"type": "rule", "text": "A conditional consists of an if-clause (hypothesis) and a main clause (result). When the if-clause comes first, we separate the clauses with a comma."}, {"type": "text", "text": "Type 0 (if + present simple -> present simple) expresses something always true / laws of nature. Type 1 (if + present simple -> future simple/imperative) expresses a possible situation in the present or future. Type 2 (if + past simple -> would + bare infinitive) expresses an imaginary or unlikely situation. We can use unless instead of if... not."}, {"type": "examples", "items": ["If you mix red and white, you get pink.", "If he is late, we'll go without him.", "If I had a computer, I would use the Internet.", "Unless he gets here soon, we'll start the meeting without him."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5c5791e5-3456-52c8-9905-7431ecd4936c','d32ebec1-89b1-50d2-bf14-1755bc656d14',0,'FILL_BLANK','Составьте условные предложения Type 0 (законы природы).',$j${"items": [{"before": "If you throw salt on snow, the snow", "after": "(melt)."}, {"before": "If you freeze water, it", "after": "(turn) into ice."}, {"before": "If you mix blue and yellow, you", "after": "(get) green."}, {"before": "If water boils, it", "after": "(produce) steam."}, {"before": "If you lie in the sun too long, your skin", "after": "(turn) red."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5c5791e5-3456-52c8-9905-7431ecd4936c',$j${"items": [{"accept": ["melts"]}, {"accept": ["turns"]}, {"accept": ["get"]}, {"accept": ["produces"]}, {"accept": ["turns"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4326a157-a955-55f3-9951-fe40fad9497d','d32ebec1-89b1-50d2-bf14-1755bc656d14',1,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "If I were you, I", "after": "go to the dentist.", "options": [{"id": "o1", "label": "would"}, {"id": "o2", "label": "will"}]}, {"before": "If it rains tomorrow, we", "after": "go to the park.", "options": [{"id": "o1", "label": "won't"}, {"id": "o2", "label": "wouldn't"}]}, {"before": "If you melted ice, it", "after": "into water.", "options": [{"id": "o1", "label": "would turn"}, {"id": "o2", "label": "turns"}]}, {"before": "If Peter had money, he", "after": "us some.", "options": [{"id": "o1", "label": "would lend"}, {"id": "o2", "label": "will lend"}]}]}$j$::jsonb,10);
