INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('0f1a81c6-7afa-5950-828d-165e7f21e147','a0000000-0000-4000-8000-0000000000a2','Блок 28. Question Tags',28,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('0699d60b-3735-529d-b8c9-90ed581343ec','0f1a81c6-7afa-5950-828d-165e7f21e147','Question Tags',0,'LESSON',70,$j$[{"type": "rule", "text": "Question tags are short questions at the end of statements, used to confirm something or find out if it is true. We form them with the auxiliary or modal verb from the main sentence and the appropriate subject pronoun."}, {"type": "text", "text": "A positive statement takes a negative tag and a negative statement takes a positive tag. With present simple we use do/does; with past simple we use did. When the sentence contains a negative word (never, rarely, seldom, hardly), the tag is positive. Special: I am -> aren't I?; Imperative -> will you?; Let's -> shall we?"}, {"type": "examples", "items": ["Philip is studying, isn't he?", "Karen works in an office, doesn't she?", "They didn't play football on Sunday, did they?", "She never complains, does she?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('56323dcf-ff23-5d02-b40e-212b96e3e4dd','0699d60b-3735-529d-b8c9-90ed581343ec',0,'CHOOSE','Выберите правильный разделительный вопрос.',$j${"items": [{"before": "You play chess well,", "after": "", "options": [{"id": "o1", "label": "don't you?"}, {"id": "o2", "label": "do you?"}]}, {"before": "William isn't a doctor,", "after": "", "options": [{"id": "o1", "label": "is he?"}, {"id": "o2", "label": "isn't he?"}]}, {"before": "Ron rarely goes to the cinema,", "after": "", "options": [{"id": "o1", "label": "does he?"}, {"id": "o2", "label": "doesn't he?"}]}, {"before": "Adam and Steven passed their exam,", "after": "", "options": [{"id": "o1", "label": "didn't they?"}, {"id": "o2", "label": "did they?"}]}, {"before": "Your sister can't swim,", "after": "", "options": [{"id": "o1", "label": "can she?"}, {"id": "o2", "label": "can't she?"}]}, {"before": "They haven't got a dog,", "after": "", "options": [{"id": "o1", "label": "have they?"}, {"id": "o2", "label": "haven't they?"}]}, {"before": "Emma never eats fish,", "after": "", "options": [{"id": "o1", "label": "does she?"}, {"id": "o2", "label": "doesn't she?"}]}]}$j$::jsonb,10);
