INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f9a2fbae-15bb-51c2-a02a-cbb5e37590ef','0699d60b-3735-529d-b8c9-90ed581343ec',1,'FILL_BLANK','Заполните пропуски правильными разделительными вопросами.',$j${"items": [{"before": "Let's go out,", "after": "?"}, {"before": "She can't see very well,", "after": "?"}, {"before": "They hardly go anywhere,", "after": "?"}, {"before": "Tony didn't do his homework,", "after": "?"}, {"before": "She is holding her son,", "after": "?"}]}$j$::jsonb,10);
