INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('68b5faac-d43f-5589-a1c3-1aa4cf75082a','a0000000-0000-4000-8000-0000000000a2','Блок 29. Adjectives & Adverbs',29,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('00ebb934-e133-58fe-992c-235c1632ca1a','68b5faac-d43f-5589-a1c3-1aa4cf75082a','Adjectives & Adverbs',0,'LESSON',70,$j$[{"type": "rule", "text": "Adjectives describe nouns and have the same form in the singular and plural. Opinion adjectives go before fact adjectives; fact adjectives usually follow the order: size, age, shape, colour, origin, material."}, {"type": "text", "text": "Adverbs describe verbs or other adverbs. We usually form an adverb by adding -ly to the adjective (quick -> quickly). Adjectives ending in consonant + y take -ily (noisy -> noisily). Adverbs of frequency go before main verbs but after auxiliary/be verbs. Some adverbs are irregular: good -> well, fast -> fast, hard -> hard, early -> early, late -> late."}, {"type": "examples", "items": ["She bought an expensive Chinese vase yesterday.", "He drives carelessly.", "He is always late for work.", "He worked hard in the garden yesterday."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2b98308f-8370-5537-9d88-ed4593c7274b','00ebb934-e133-58fe-992c-235c1632ca1a',0,'REORDER','Расставьте прилагательные в правильном порядке.',$j${"tiles": ["wooden", "round", "table"]}$j$::jsonb,10);
