INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d5368bf8-33ed-5f0c-867e-69d7cac81c26','a0000000-0000-4000-8000-0000000000a2','Блок 30. Comparatives & Superlatives',30,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2e3507d6-9d6a-5e96-ae76-91a4c41e7df8','d5368bf8-33ed-5f0c-867e-69d7cac81c26','Comparatives & Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the comparative to compare two people/things and can use than. We use the superlative to compare one with more than one in the same group, using the ... of/in (in for places)."}, {"type": "text", "text": "One- and two-syllable adjectives form the comparative with -er and the superlative with -est. Adjectives ending in -y change -y to i (busy -> busier -> the busiest). Adjectives of more than two syllables use more/the most. Irregular: good -> better -> the best, bad -> worse -> the worst, far -> farther/further -> the farthest/furthest. We use much + comparative and very + adjective."}, {"type": "examples", "items": ["Mark is older than George.", "Mt Everest is the tallest mountain in the world.", "London is much bigger than Manchester.", "Elephants are the heaviest land animals in the world."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5b88f444-fdb5-5e6b-ad01-b0162071c59c','2e3507d6-9d6a-5e96-ae76-91a4c41e7df8',0,'FILL_BLANK','Заполните пропуски сравнительной или превосходной формой наречия в скобках.',$j${"items": [{"before": "She drives", "after": "(carefully) than her sister."}, {"before": "Helen works", "after": "(hard) of all."}, {"before": "Ben swims", "after": "(fast) than me."}, {"before": "We left the party", "after": "(late) than you."}, {"before": "She dances", "after": "(beautifully) of all."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5b88f444-fdb5-5e6b-ad01-b0162071c59c',$j${"items": [{"accept": ["more carefully"]}, {"accept": ["the hardest"]}, {"accept": ["faster"]}, {"accept": ["later"]}, {"accept": ["the most beautifully"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('127dbed6-5d95-526a-be7f-8a0ecee4c947','2e3507d6-9d6a-5e96-ae76-91a4c41e7df8',1,'FILL_BLANK','Заполните пропуски словами of, than, in или the.',$j${"items": [{"before": "Neptune is", "after": "coldest planet in our solar system."}, {"before": "A car can travel much faster", "after": "a bicycle."}, {"before": "Jane is the prettiest girl", "after": "the class."}, {"before": "He likes cricket more", "after": "football."}, {"before": "The tallest building", "after": "the world is the Burj Dubai."}, {"before": "Kim is older", "after": "Colin."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('127dbed6-5d95-526a-be7f-8a0ecee4c947',$j${"items": [{"accept": ["the"]}, {"accept": ["than"]}, {"accept": ["in"]}, {"accept": ["than"]}, {"accept": ["in"]}, {"accept": ["than"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('967353c6-e22c-5904-8319-12d34701613b','2e3507d6-9d6a-5e96-ae76-91a4c41e7df8',2,'CHOOSE','Выберите very или much.',$j${"items": [{"before": "This dress costs", "after": "more than that one.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "This film isn't", "after": "interesting.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}, {"before": "I find history", "after": "more interesting.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "Suzanne works", "after": "hard.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}]}$j$::jsonb,10);
