INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a846d3a5-057b-55f6-87ec-defe27de6a8c','a0000000-0000-4000-8000-0000000000a2','Блок 31. Comparatives and Superlatives',31,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c61307e9-513f-50fc-be2d-c767c1c65afd','a846d3a5-057b-55f6-87ec-defe27de6a8c','Comparatives and Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "For short adjectives add -er to form the comparative (used with 'than') and -est for the superlative (used with 'the'). For long adjectives use 'more' + adjective + 'than' and 'the most' + adjective."}, {"type": "rule", "text": "Irregular forms: good/well -> better -> best; bad/badly -> worse -> worst; far -> farther/further; much -> more -> most."}, {"type": "rule", "text": "We use 'than' after a comparative. To make a comparative stronger we use 'much' (not 'very'): Nancy runs much faster than me."}, {"type": "examples", "items": ["Southern Europe is warmer than Northern Europe.", "New York is the most exciting city in the USA.", "Lake Tanganyika is the deepest lake in Africa.", "Joe is taller than Kate. Kate is taller than Sam. Joe is the tallest."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6921541e-eaff-5661-8151-7596a346070c','c61307e9-513f-50fc-be2d-c767c1c65afd',0,'FILL_BLANK','Поставьте прилагательное или наречие в скобках в форму сравнительной или превосходной степени.',$j${"items": [{"before": "Southern Europe is", "after": "than Northern Europe. (warm)"}, {"before": "Tony plays squash", "after": "than me. (well)"}, {"before": "New York is", "after": "city in the USA. (exciting)"}, {"before": "She came", "after": "than her parents. (early)"}, {"before": "Lake Tanganyika is", "after": "lake in Africa. (deep)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6921541e-eaff-5661-8151-7596a346070c',$j${"items": [{"accept": ["warmer"]}, {"accept": ["better"]}, {"accept": ["the most exciting"]}, {"accept": ["earlier"]}, {"accept": ["the deepest"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('33ed3810-e0b3-55a7-9674-48b493af3ebc','c61307e9-513f-50fc-be2d-c767c1c65afd',1,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "Today is hotter", "after": "yesterday.", "options": [{"id": "o1", "label": "than"}, {"id": "o2", "label": "of"}]}, {"before": "Helen isn't as", "after": "as her sister.", "options": [{"id": "o1", "label": "taller"}, {"id": "o2", "label": "tall"}]}, {"before": "Tracey is", "after": "thinner than Laura.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "I think 'The Independent' is", "after": "newspaper in the UK.", "options": [{"id": "o1", "label": "the better"}, {"id": "o2", "label": "the best"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('33ed3810-e0b3-55a7-9674-48b493af3ebc',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
