INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('9a6f2ad8-6ce4-546d-81e2-40de8ca6ba53','a0000000-0000-4000-8000-0000000000a2','Блок 32. Too - Enough / As ... as / Less',32,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('352defe2-c25d-57e4-a14b-5ae6384be6a4','9a6f2ad8-6ce4-546d-81e2-40de8ca6ba53','Too - Enough / As ... as / Less',0,'LESSON',70,$j$[{"type": "rule", "text": "'too' comes before an adjective and has a negative meaning: something is more than necessary. Structure: too + adjective + to-infinitive. The coffee is too hot to drink."}, {"type": "rule", "text": "'enough' comes after an adjective but before a noun and has a positive meaning: adjective + enough / enough + noun + to-infinitive. She is old enough to walk to school alone. We have enough money to go on holiday."}, {"type": "rule", "text": "'not ... enough' has a negative meaning: She is not strong enough to lift the suitcase."}, {"type": "rule", "text": "We use (not) as + adjective + as to show that things are (not) similar. We use 'less' + adjective (positive form) + than to show inferiority. Fiona is not as thin as Sue. This dress is less expensive than that one."}, {"type": "examples", "items": ["This watch is too expensive for me to buy.", "The boxes are light enough to carry.", "Jamie is as old as Susie."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('47017fe2-aca8-5d63-814b-db88354deaf4','352defe2-c25d-57e4-a14b-5ae6384be6a4',0,'CHOOSE','Дополните предложения словом too или enough.',$j${"items": [{"before": "It's", "after": "noisy in here. I can't do my homework.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "My little sister isn't tall", "after": "to reach the top shelf.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "The kitten won't come near us. It's", "after": "scared.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "I haven't got", "after": "flour to make a cake.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "There isn't", "after": "room in the car for seven people.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "She isn't old", "after": "to get married.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('47017fe2-aca8-5d63-814b-db88354deaf4',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e8cf37ca-286e-5505-93e2-8c360e31a28d','352defe2-c25d-57e4-a14b-5ae6384be6a4',1,'CHOOSE','Заполните пропуски словами too, enough, as или less.',$j${"items": [{"before": "This vase is", "after": "expensive than that one.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}, {"before": "The soup is", "after": "hot to eat.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}, {"before": "He isn't", "after": "hardworking as Doug.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}, {"before": "This book is", "after": "interesting than this one.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}, {"before": "Bill isn't well", "after": "to go back to work.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}, {"before": "She's", "after": "tall as her sister.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}, {"id": "o3", "label": "as"}, {"id": "o4", "label": "less"}]}]}$j$::jsonb,10);
