INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e38cbfc1-5ab5-5318-8775-31c8d5b6baed','a0000000-0000-4000-8000-0000000000a2','Блок 33. Present Perfect',33,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7f9f5b93-cc33-505d-84e2-893070222244','e38cbfc1-5ab5-5318-8775-31c8d5b6baed','Present Perfect',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the present perfect with the auxiliary 'have/has' and the past participle. Regular verbs add -ed (live -> lived); irregular verbs have special forms (sit -> sat)."}, {"type": "rule", "text": "We use the present perfect for: actions that started in the past and still continue; recently finished actions with visible results; experiences; and actions that happened at an unspecified time in the past."}, {"type": "rule", "text": "Questions: put have/has before the subject (Have you seen our new car?). Negations: put 'not' after have/has (Paul hasn't finished yet)."}, {"type": "rule", "text": "Time expressions: already, yet, just, ever, never, for, since, recently, so far, this week/month/year."}, {"type": "examples", "items": ["He has worked as a doctor since 1990.", "They have done their shopping.", "This is the best book I have ever read.", "I have read three books this month."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3aea3168-458f-59e0-a697-4ec1f9da2841','7f9f5b93-cc33-505d-84e2-893070222244',0,'FILL_BLANK','Поставьте глаголы в скобках в форму present perfect.',$j${"items": [{"before": "Do you know Henry? Yes, I", "after": "him once before. (meet)"}, {"before": "What time does the plane take off? It", "after": ". (just / take off)"}, {"before": "Did Sally like these biscuits? She", "after": "them yet. (not / taste)"}, {"before": "How's Philip? I don't know. I", "after": "to him since Tuesday. (not / speak)"}, {"before": "Can I read your magazine? Sorry! I", "after": "with it yet. (not / finish)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3aea3168-458f-59e0-a697-4ec1f9da2841',$j${"items": [{"accept": ["have met", "'ve met"]}, {"accept": ["has just taken off", "'s just taken off"]}, {"accept": ["hasn't tasted", "has not tasted"]}, {"accept": ["haven't spoken", "have not spoken"]}, {"accept": ["haven't finished", "have not finished"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e2d9c460-9baa-500f-b042-61e4d28bf217','7f9f5b93-cc33-505d-84e2-893070222244',1,'FILL_BLANK','Заполните пропуски правильным словом (for, since, so far, just, ever, never).',$j${"items": [{"before": "William has been ill", "after": "Sunday."}, {"before": "We have been to the theatre twice", "after": "."}, {"before": "I have", "after": "finished my report. I finished it five minutes ago."}, {"before": "Betty and Julie have been friends", "after": "many years."}, {"before": "This is the most beautiful place I have", "after": "seen."}, {"before": "I have", "after": "been to China. I hope I'll go some day."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e2d9c460-9baa-500f-b042-61e4d28bf217',$j${"items": [{"accept": ["since"]}, {"accept": ["so far"]}, {"accept": ["just"]}, {"accept": ["for"]}, {"accept": ["ever"]}, {"accept": ["never"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cf5e6360-4f38-58b9-996c-4c12ef4d9952','7f9f5b93-cc33-505d-84e2-893070222244',2,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "Amy hasn't graduated from university", "after": ".", "options": [{"id": "o1", "label": "yet"}, {"id": "o2", "label": "already"}]}, {"before": "They have been friends", "after": "1990.", "options": [{"id": "o1", "label": "since"}, {"id": "o2", "label": "for"}]}, {"before": "Peter has", "after": "washed the car.", "options": [{"id": "o1", "label": "already"}, {"id": "o2", "label": "ever"}]}, {"before": "Has he", "after": "travelled to Italy?", "options": [{"id": "o1", "label": "ever"}, {"id": "o2", "label": "yet"}]}, {"before": "My brother has", "after": "won the competition.", "options": [{"id": "o1", "label": "just"}, {"id": "o2", "label": "ever"}]}, {"before": "Liz has been on the phone", "after": "ages!", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cf5e6360-4f38-58b9-996c-4c12ef4d9952',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
