INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('12783db8-84e2-5029-874f-65b0afad6b52','a0000000-0000-4000-8000-0000000000a2','Блок 34. Have gone (to) - Have been (to)',34,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a7fa311a-5640-53bb-844b-e25499cc610c','12783db8-84e2-5029-874f-65b0afad6b52','Have gone (to) - Have been (to)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'have/has gone (to)' to say that someone went somewhere and is still there (they haven't come back yet)."}, {"type": "rule", "text": "We use 'have/has been (to)' to say that someone went somewhere but has come back."}, {"type": "examples", "items": ["They have gone on a safari. (They are still there.)", "She's been to India twice. (She went, but she has come back.)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fb7a0357-159e-53a8-b16a-c59e5d9dfa20','a7fa311a-5640-53bb-844b-e25499cc610c',0,'CHOOSE','Выберите правильную форму: been to или gone to.',$j${"items": [{"before": "David speaks Spanish very well because he has", "after": "Spain many times.", "options": [{"id": "o1", "label": "been to"}, {"id": "o2", "label": "gone to"}]}, {"before": "The children aren't here. They have", "after": "their friend's house.", "options": [{"id": "o1", "label": "been to"}, {"id": "o2", "label": "gone to"}]}, {"before": "Claire and Alex have", "after": "Rome for the weekend.", "options": [{"id": "o1", "label": "been to"}, {"id": "o2", "label": "gone to"}]}, {"before": "I have", "after": "Florence and Venice, but not Rome.", "options": [{"id": "o1", "label": "been to"}, {"id": "o2", "label": "gone to"}]}, {"before": "I have never", "after": "Spain.", "options": [{"id": "o1", "label": "been to"}, {"id": "o2", "label": "gone to"}]}]}$j$::jsonb,10);
