INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('af1fdb01-ccc2-5a5e-be49-6de128a83bad','a0000000-0000-4000-8000-0000000000a2','Блок 35. Present Perfect vs Past Simple',35,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8109edd9-08f6-550f-ae95-4f55731f62df','af1fdb01-ccc2-5a5e-be49-6de128a83bad','Present Perfect vs Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present perfect for actions that happened at an unstated time in the past and for actions that started in the past and still continue. Time expressions: for, since, yet, already, just."}, {"type": "rule", "text": "We use the past simple for actions that happened at a stated time in the past and for actions that started and finished in the past. Time expressions: ago, yesterday, last week/month/year."}, {"type": "examples", "items": ["She has had an operation. (When? We don't know.)", "Chloe started ballet classes last week. (When? Last week.)", "Claire has worked in this camera shop for three years. (She still works there.)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7cdae76c-9c2c-5271-8807-e39a0f0cec30','8109edd9-08f6-550f-ae95-4f55731f62df',0,'FILL_BLANK','Поставьте глаголы в скобках в present perfect или past simple.',$j${"items": [{"before": "Olivia", "after": "her room an hour ago. (clean)"}, {"before": "Denise", "after": "Spanish lessons last summer. (take)"}, {"before": "Jack", "after": "his wife three times so far this morning. (call)"}, {"before": "We", "after": "to Ben for a long time. (not / speak)"}, {"before": "I", "after": "at work since 9 o'clock this morning. (be)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('7cdae76c-9c2c-5271-8807-e39a0f0cec30',$j${"items": [{"accept": ["cleaned"]}, {"accept": ["took"]}, {"accept": ["has called", "'s called"]}, {"accept": ["haven't spoken", "have not spoken"]}, {"accept": ["have been", "'ve been"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('68b862fc-a4a1-513e-b708-a628e61b86ba','8109edd9-08f6-550f-ae95-4f55731f62df',1,'MATCH_PAIRS','Соедините часть A с частью B.',$j${"left": [{"id": "l1", "label": "They went to Australia"}, {"id": "l2", "label": "We haven't heard"}, {"id": "l3", "label": "The Smiths have visited"}, {"id": "l4", "label": "Rita! I haven't seen"}, {"id": "l5", "label": "I finished my report"}, {"id": "l6", "label": "John lived in Rome"}, {"id": "l7", "label": "Alice hasn't played the violin"}, {"id": "l8", "label": "He hasn't travelled"}], "right": [{"id": "r1", "label": "to visit their cousins last winter."}, {"id": "r2", "label": "from Molly for two weeks."}, {"id": "r3", "label": "five Asian countries so far."}, {"id": "r4", "label": "you for a long time!"}, {"id": "r5", "label": "ten minutes ago."}, {"id": "r6", "label": "for five years before he returned to England."}, {"id": "r7", "label": "since she was 12."}, {"id": "r8", "label": "abroad since 2004."}]}$j$::jsonb,10);
