INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2fba48e1-3798-5fd1-8e3a-ebf3cac448c2','a0000000-0000-4000-8000-0000000000a2','Блок 36. Countable / Uncountable Nouns - A/An - Some/Any - Every',36,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4bb1e396-ac19-5d66-a5ac-a0be3d480145','2fba48e1-3798-5fd1-8e3a-ebf3cac448c2','Countable / Uncountable Nouns - A/An - Some/Any - Every',0,'LESSON',70,$j$[{"type": "rule", "text": "Countable nouns can be counted and have singular and plural forms (one hat, two hats). Uncountable nouns cannot be counted and usually have no plural form (cheese)."}, {"type": "rule", "text": "We use a/an with singular countable nouns in affirmative, negative and interrogative sentences. We use 'some' in affirmative sentences with plural countable and uncountable nouns; we can also use 'some' in questions to make an offer or a request."}, {"type": "rule", "text": "We use 'any' in negative and interrogative sentences with plural countable and uncountable nouns. We use 'every' before singular countable nouns."}, {"type": "examples", "items": ["There is some bread. There are some potatoes.", "There aren't any eggs. Are there any peppers?", "Would you like some biscuits? (offer)", "Every person in my family has got their own car."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6462f87f-1962-5bd3-b3e8-3763b1d5bbcc','4bb1e396-ac19-5d66-a5ac-a0be3d480145',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "Are there", "after": "tomatoes in the fridge?", "options": [{"id": "o1", "label": "any"}, {"id": "o2", "label": "some"}]}, {"before": "Would you like", "after": "orange?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "Tracey has got", "after": "beautiful house.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "Tom goes to the gym", "after": "day.", "options": [{"id": "o1", "label": "every"}, {"id": "o2", "label": "some"}]}, {"before": "We need", "after": "flour to make a cake.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Can I have", "after": "bread, please?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Is there", "after": "bottle of ketchup in the fridge?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "Claire has got a guitar lesson", "after": "Tuesday.", "options": [{"id": "o1", "label": "every"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
