INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('268e1dca-cdcf-545e-90f7-8b8a2ba58e8e','4bb1e396-ac19-5d66-a5ac-a0be3d480145',1,'CHOOSE','Дополните диалог словами a, some или any.',$j${"items": [{"before": "I've got some fruit,", "after": "sandwiches.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "and", "after": "packet of crisps.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "Have you got", "after": "drinks?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "Yes, I've got", "after": "juice.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "and", "after": "bottle of coke.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}, {"before": "Have you got", "after": "plastic plates?", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}, {"id": "o3", "label": "any"}]}]}$j$::jsonb,10);
