INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('755d534f-8db7-538d-955b-36d7ebf8ccde','a0000000-0000-4000-8000-0000000000a2','Блок 37. Some / Any / No / Every + body(one) / thing / where',37,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2f0f9d23-4d6f-5ffd-b68c-b3bd9eaa8ecb','755d534f-8db7-538d-955b-36d7ebf8ccde','Some / Any / No / Every + body(one) / thing / where',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'some' and its compounds (someone/somebody, something, somewhere) in positive sentences, and in questions to make an offer, a request or when we expect a positive answer."}, {"type": "rule", "text": "We use 'any' and its compounds (anyone/anybody, anything, anywhere) in negative and interrogative sentences. In positive sentences they mean 'it doesn't matter who/which/what/where'."}, {"type": "rule", "text": "We use 'no' and its compounds (no one/nobody, nothing, nowhere) in negative sentences (with a positive verb). We use 'every' and its compounds (everyone/everybody, everything, everywhere) with a singular verb."}, {"type": "examples", "items": ["There is someone at the door.", "There isn't any cake left.", "There's nobody at home.", "Everything is ready for the party."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('896af168-dda6-5086-a8ef-f2af6e07dc94','2f0f9d23-4d6f-5ffd-b68c-b3bd9eaa8ecb',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "We went shopping but we didn't buy", "after": ".", "options": [{"id": "o1", "label": "something"}, {"id": "o2", "label": "anything"}]}, {"before": "When I came home,", "after": "had gone out.", "options": [{"id": "o1", "label": "someone"}, {"id": "o2", "label": "everyone"}]}, {"before": "", "after": "in this shop is half price.", "options": [{"id": "o1", "label": "Anything"}, {"id": "o2", "label": "Everything"}]}, {"before": "", "after": "came to my party and I was very sad.", "options": [{"id": "o1", "label": "Nobody"}, {"id": "o2", "label": "Anybody"}]}, {"before": "I left my glasses", "after": "in the house.", "options": [{"id": "o1", "label": "somewhere"}, {"id": "o2", "label": "anywhere"}]}, {"before": "Does", "after": "have a pen I can borrow?", "options": [{"id": "o1", "label": "anyone"}, {"id": "o2", "label": "someone"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('896af168-dda6-5086-a8ef-f2af6e07dc94',$j${"items": [{"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b93001bf-8dd4-54f7-8275-1e258e71855b','2f0f9d23-4d6f-5ffd-b68c-b3bd9eaa8ecb',1,'FILL_BLANK','Заполните пропуски словами something, someone, anything, anywhere, nobody или nowhere.',$j${"items": [{"before": "I think there's", "after": "at the door."}, {"before": "Could", "after": "help me fix this?"}, {"before": "I'm hungry. I want to eat", "after": "."}, {"before": "Are you doing", "after": "tonight?"}, {"before": "Have you seen my car keys", "after": "?"}, {"before": "I called the restaurant but", "after": "answered."}]}$j$::jsonb,10);
