INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('fa2d4c80-3484-5b65-8073-f80bc8eae6d7','a0000000-0000-4000-8000-0000000000a2','Блок 38. A lot of - Much / Many - A few / Few - A little / Little',38,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1db9c729-e093-5dc1-8033-bb13bdf8a7fb','fa2d4c80-3484-5b65-8073-f80bc8eae6d7','A lot of - Much / Many - A few / Few - A little / Little',0,'LESSON',70,$j$[{"type": "rule", "text": "We normally use 'a lot of / lots of' in affirmative sentences with plural countable and uncountable nouns. We omit 'of' when 'a lot / lots' is not followed by a noun (Yes, I've got a lot)."}, {"type": "rule", "text": "We normally use 'much' and 'many' in questions and negations. 'much' is followed by uncountable nouns; 'many' by plural countable nouns. We use 'how much' (amount) and 'how many' (number) in questions."}, {"type": "rule", "text": "'too much' (uncountable) and 'too many' (plural countable) have a negative meaning: more than is wanted or needed."}, {"type": "rule", "text": "We use 'a few/few' with plural countable nouns and 'a little/little' with uncountable nouns. 'a few / a little' = not many/much but enough; 'few / little' = hardly any/almost none."}, {"type": "examples", "items": ["Laura's got a lot of DVDs.", "Is there much tea in the teapot? I haven't got many photos.", "I've got a few lemons. She's got a little time.", "There are very few biscuits in the box."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('90ce772e-3df8-5746-a709-4f7dba872e99','1db9c729-e093-5dc1-8033-bb13bdf8a7fb',0,'CHOOSE','Заполните пропуски: too much или too many.',$j${"items": [{"before": "He's got", "after": "books. He doesn't know where to put them all.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}, {"before": "Don't eat", "after": "sweets. They are bad for your teeth.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}, {"before": "I spent", "after": "money this month. I can't pay my bills now.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}, {"before": "You put", "after": "sugar in my coffee. It's too sweet now.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}, {"before": "There were", "after": "people at the party last night.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}, {"before": "There's", "after": "traffic today. We won't get to work on time.", "options": [{"id": "o1", "label": "too much"}, {"id": "o2", "label": "too many"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('90ce772e-3df8-5746-a709-4f7dba872e99',$j${"items": [{"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('bfeb6c2d-4265-5bbf-945b-5d412be57458','1db9c729-e093-5dc1-8033-bb13bdf8a7fb',1,'CHOOSE','Заполните пропуски: (a) few или (a) little.',$j${"items": [{"before": "How much milk do you want? Only", "after": ", please.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}, {"before": "What did you do during your flight? I read", "after": "magazines and I slept.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}, {"before": "Is there any cake left? There's very", "after": "left.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}, {"before": "Do you speak Spanish? No, I know very", "after": "words in Spanish.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}, {"before": "I'm only going away for", "after": "days.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}, {"before": "We must hurry. That's true. We have very", "after": "time.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}, {"id": "o3", "label": "little"}, {"id": "o4", "label": "few"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('bfeb6c2d-4265-5bbf-945b-5d412be57458',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o4"}, {"correctId": "o2"}, {"correctId": "o3"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('07a571b3-fe8b-5b88-be6a-02df7765f9cc','1db9c729-e093-5dc1-8033-bb13bdf8a7fb',2,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "How", "after": "milk do you drink every day?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "There is", "after": "flour in the cupboard.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a lot of"}]}, {"before": "How", "after": "eggs do you need to make an omelette?", "options": [{"id": "o1", "label": "many"}, {"id": "o2", "label": "much"}]}, {"before": "There isn't", "after": "coffee left. We need to buy some.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "We've got", "after": "apples. Let's make an apple pie.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "Are you hungry? There's", "after": "chicken left.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}]}]}$j$::jsonb,10);
