INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('132f315c-9a74-52cb-9ded-774b072321bd','a0000000-0000-4000-8000-0000000000a2','Блок 39. Modal Verbs: Can, Could, Must, Have to, Should',39,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8754c216-6b0b-5892-8f51-3b18f9422d38','132f315c-9a74-52cb-9ded-774b072321bd','Modal Verbs: Can, Could, Must, Have to, Should',0,'LESSON',70,$j$[{"type": "rule", "text": "We use can to express ability, ask for and give permission, and express possibility in the present. We use could to express general ability in the past."}, {"type": "examples", "items": ["He can sing very well.", "Can I use your phone?", "You can take my car tonight.", "He could play football when he was young."]}, {"type": "rule", "text": "We use must/mustn't to express obligation, strong advice or prohibition. We use have to for obligation and necessity, and don't have to/needn't for lack of obligation."}, {"type": "examples", "items": ["You must keep your room clean.", "You mustn't park here.", "Philip has to wear a suit and tie to work.", "You needn't bring a camera. I have one."]}, {"type": "rule", "text": "We use should/ought to to give advice."}, {"type": "examples", "items": ["You should look both ways before you cross the road.", "You shouldn't eat too much chocolate."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5e3e9ee3-bf25-510e-a9a6-7ca3dd2bd678','8754c216-6b0b-5892-8f51-3b18f9422d38',0,'FILL_BLANK','Заполните пропуски: can, can''t, could или couldn''t.',$j${"items": [{"before": "They", "after": "drive yet. They're only 15 years old."}, {"before": "When he was four years old, he", "after": "only count to twenty."}, {"before": "It was raining yesterday, so we", "after": "go on a picnic."}, {"before": "", "after": "you speak German when you were little?"}, {"before": "David", "after": "come to the phone right now. He's busy."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5e3e9ee3-bf25-510e-a9a6-7ca3dd2bd678',$j${"items": [{"accept": ["can't", "cannot"]}, {"accept": ["could"]}, {"accept": ["couldn't", "could not"]}, {"accept": ["Could", "could"]}, {"accept": ["can't", "cannot"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8e61ac59-8e20-5d8c-8839-f4e7ceeac34b','8754c216-6b0b-5892-8f51-3b18f9422d38',1,'FILL_BLANK','Заполните пропуски правильной формой: have to, has to или don''t have to/needn''t.',$j${"items": [{"before": "He can't come with us. He", "after": "work."}, {"before": "Liz", "after": "get up early tomorrow. There's no school."}, {"before": "Steven is a soldier. He", "after": "wear a uniform."}, {"before": "You've got plenty of time. You", "after": "hurry."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8e61ac59-8e20-5d8c-8839-f4e7ceeac34b',$j${"items": [{"accept": ["has to"]}, {"accept": ["doesn't have to", "needn't", "does not have to"]}, {"accept": ["has to"]}, {"accept": ["don't have to", "needn't", "do not have to"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7022747e-b906-5c56-80c2-57a07e5e8bc7','8754c216-6b0b-5892-8f51-3b18f9422d38',2,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "She", "after": "study hard if she wants to pass the test.", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "has to"}, {"id": "o3", "label": "doesn't have to"}]}, {"before": "He", "after": "swim when he was three years old.", "options": [{"id": "o1", "label": "shouldn't"}, {"id": "o2", "label": "can't"}, {"id": "o3", "label": "couldn't"}]}, {"before": "She", "after": "go to the meeting if she doesn't want to.", "options": [{"id": "o1", "label": "has to"}, {"id": "o2", "label": "doesn't have to"}, {"id": "o3", "label": "must"}]}, {"before": "You", "after": "eat so many sweets. They're bad for your teeth.", "options": [{"id": "o1", "label": "couldn't"}, {"id": "o2", "label": "can't"}, {"id": "o3", "label": "shouldn't"}]}]}$j$::jsonb,10);
