INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e2372e39-cc5b-5f90-bd2e-b01b2550489a','8754c216-6b0b-5892-8f51-3b18f9422d38',3,'CHOOSE','Выберите правильный модальный глагол.',$j${"items": [{"before": "You", "after": "have a passport to travel abroad.", "options": [{"id": "o1", "label": "have to"}, {"id": "o2", "label": "can"}]}, {"before": "You mustn't keep pets in the building.", "after": "It's against the rules.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "shouldn't"}]}, {"before": "My sister", "after": "read yet. She's too young.", "options": [{"id": "o1", "label": "couldn't"}, {"id": "o2", "label": "can't"}]}, {"before": "You really", "after": "drive so fast. It's dangerous.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "can't"}]}]}$j$::jsonb,10);
