INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cf5eee11-4f5f-5919-8c4f-1d62a84afd54','8754c216-6b0b-5892-8f51-3b18f9422d38',4,'FILL_BLANK','Замените слова в скобках одним модальным глаголом (must, can, should, can''t, couldn''t, mustn''t, don''t have to).',$j${"items": [{"before": "He is able to dance well. He", "after": "dance well."}, {"before": "It was too noisy; I wasn't able to sleep. I", "after": "sleep."}, {"before": "It isn't necessary to wear a uniform to school. We", "after": "wear a uniform."}]}$j$::jsonb,10);
