INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d409bafa-64e1-5cbe-8e2e-0c9a516c4174','a0000000-0000-4000-8000-0000000000a2','Блок 40. Relative Pronouns and Relative Clauses',40,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('22b41a51-efa7-5593-9d4f-7ca459f028cd','d409bafa-64e1-5cbe-8e2e-0c9a516c4174','Relative Pronouns and Relative Clauses',0,'LESSON',70,$j$[{"type": "rule", "text": "Relative pronouns (who, which, whose, that) introduce relative clauses. We use who/that for people, which/that for objects or animals, and whose to show possession."}, {"type": "examples", "items": ["The boy who/that is playing the guitar is Philip.", "The car which/that won the race is red.", "That's the woman whose son is a doctor."]}, {"type": "rule", "text": "A defining relative clause gives necessary information and is not put in commas. A non-defining relative clause gives extra information, is put in commas, and we cannot use that or omit the relative pronoun."}, {"type": "examples", "items": ["The woman who/that lives next door is a teacher.", "My uncle Peter, who lives in New York, is an architect."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('43b33d90-4b5c-59e5-992e-b3d80c11bf0c','22b41a51-efa7-5593-9d4f-7ca459f028cd',0,'FILL_BLANK','Заполните пропуски: who, which или whose.',$j${"items": [{"before": "Brian is the student", "after": "father is a painter."}, {"before": "The box", "after": "is on the table is your birthday present."}, {"before": "Graham Bell is the man", "after": "invented the telephone."}, {"before": "What's the name of the boy", "after": "lives next door?"}, {"before": "Is this the woman", "after": "husband is a lawyer?"}, {"before": "My mother,", "after": "name is Sarah, is a doctor."}, {"before": "Kangaroos are animals", "after": "live in Australia."}]}$j$::jsonb,10);
