INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f789723a-2c6c-5b43-8cc7-d4778fbf8cc6','22b41a51-efa7-5593-9d4f-7ca459f028cd',2,'FILL_BLANK','Заполните пропуски правильным относительным местоимением (who, which или whose).',$j${"items": [{"before": "E.T. tells the story of a boy called Elliot", "after": "finds a friendly alien called E.T."}, {"before": "E.T.,", "after": "spaceship accidentally left him behind on Earth, becomes his friend."}, {"before": "Elliot,", "after": "is frightened by E.T. at first, eventually becomes friends with him."}, {"before": "Elliot and his brother form a plan", "after": "will help E.T. return home."}]}$j$::jsonb,10);
