INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('581a3316-16a7-5367-b359-94e2904370c3','22b41a51-efa7-5593-9d4f-7ca459f028cd',3,'CHOOSE','Выберите правильное относительное местоимение.',$j${"items": [{"before": "Mount Vesuvius is the volcano", "after": "destroyed Pompeii.", "options": [{"id": "o1", "label": "which"}, {"id": "o2", "label": "who"}, {"id": "o3", "label": "whose"}]}, {"before": "Mel Gibson is the actor", "after": "starred in all the Lethal Weapon films.", "options": [{"id": "o1", "label": "which"}, {"id": "o2", "label": "whose"}, {"id": "o3", "label": "who"}]}, {"before": "The girl", "after": "is sitting next to Tony is my cousin.", "options": [{"id": "o1", "label": "that"}, {"id": "o2", "label": "whose"}, {"id": "o3", "label": "which"}]}, {"before": "The Great Fire of London,", "after": "happened in 1666, caused great damage to the city.", "options": [{"id": "o1", "label": "whose"}, {"id": "o2", "label": "which"}, {"id": "o3", "label": "who"}]}]}$j$::jsonb,10);
