INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c8e06e5b-61dd-5344-b606-47485bc16ee2','a0000000-0000-4000-8000-0000000000a2','Блок 41. The Passive (Present Simple, Past Simple)',41,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('fa5665b2-9423-568b-a433-6abcb05a2f9e','c8e06e5b-61dd-5344-b606-47485bc16ee2','The Passive (Present Simple, Past Simple)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the passive with the verb to be in the appropriate tense and the past participle of the main verb. The object of the active sentence becomes the subject of the passive sentence."}, {"type": "examples", "items": ["Careless drivers cause a lot of accidents. -> A lot of accidents are caused by careless drivers.", "A careless driver caused the accident. -> The accident was caused by a careless driver."]}, {"type": "rule", "text": "We introduce the agent with by + person or with + object/instrument. The agent is not mentioned when it is unknown, unimportant or obvious from the context."}, {"type": "examples", "items": ["The Eiffel Tower was designed by Gustave Eiffel.", "The mail is delivered every day."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a3574746-f2b0-59d9-b11a-6750550d0129','fa5665b2-9423-568b-a433-6abcb05a2f9e',0,'FILL_BLANK','Заполните пропуски: is, are, was или were.',$j${"items": [{"before": "A talent show competition", "after": "organised by our school every year."}, {"before": "Chevrolet cars", "after": "made in America."}, {"before": "A documentary on dinosaurs", "after": "shown on TV last Saturday."}, {"before": "We", "after": "invited to a barbecue last week."}, {"before": "The Olympics", "after": "held every four years."}, {"before": "The building", "after": "destroyed by a fire last year."}, {"before": "The offices", "after": "cleaned twice a week."}, {"before": "The TV", "after": "invented by John Baird in 1926."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a3574746-f2b0-59d9-b11a-6750550d0129',$j${"items": [{"accept": ["is"]}, {"accept": ["are"]}, {"accept": ["was"]}, {"accept": ["were"]}, {"accept": ["are"]}, {"accept": ["was"]}, {"accept": ["are"]}, {"accept": ["was"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0ffa97a1-85e7-580a-bd5c-d3bd7edfff81','fa5665b2-9423-568b-a433-6abcb05a2f9e',1,'FILL_BLANK','Раскройте скобки, употребив глагол в present simple passive или past simple passive.',$j${"items": [{"before": "This vase", "after": "of clay. [make]"}, {"before": "Helen has a bandage because she", "after": "by a dog yesterday. [bite]"}, {"before": "The birds", "after": "once a day, that's all. [feed]"}, {"before": "The Oscars", "after": "every year at the end of February. [hold]"}, {"before": "The necklace", "after": "to me last year on my graduation day. [give]"}, {"before": "This house", "after": "in 1950. [build]"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0ffa97a1-85e7-580a-bd5c-d3bd7edfff81',$j${"items": [{"accept": ["is made"]}, {"accept": ["was bitten"]}, {"accept": ["are fed"]}, {"accept": ["are held"]}, {"accept": ["was given"]}, {"accept": ["was built"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f42d6105-750b-580c-a4bd-d1a197e4d932','fa5665b2-9423-568b-a433-6abcb05a2f9e',2,'FILL_BLANK','Заполните пропуски глаголами из списка в present simple passive или past simple passive: discover, invite, buy, build, post, make, invent, serve, employ.',$j${"items": [{"before": "The telephone", "after": "by A.G. Bell."}, {"before": "The invitations", "after": "yesterday."}, {"before": "The hotel", "after": "in the 18th century."}, {"before": "Yoghurt", "after": "from milk."}, {"before": "Breakfast", "after": "at 7:30 every morning."}, {"before": "Penicillin", "after": "by Alexander Fleming."}, {"before": "A lot of books", "after": "online every day."}, {"before": "200 people", "after": "in the company."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f42d6105-750b-580c-a4bd-d1a197e4d932',$j${"items": [{"accept": ["was invented"]}, {"accept": ["were posted"]}, {"accept": ["was built"]}, {"accept": ["is made"]}, {"accept": ["is served"]}, {"accept": ["was discovered"]}, {"accept": ["are bought"]}, {"accept": ["are employed"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8d405f6e-422c-5683-a128-6c84e7d942fa','fa5665b2-9423-568b-a433-6abcb05a2f9e',3,'SHORT_TEXT','Перепишите предложение в present simple passive. Пример: A screenwriter writes the script. -> The script is written by a screenwriter.',$j${"question": "A director directs the film."}$j$::jsonb,10);
