INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('01145907-4c06-5f90-bd59-14a940f434a5','a0000000-0000-4000-8000-0000000000a2','Блок 42. Will, Be Going To, Present Continuous (Future)',42,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1af85fad-66d1-5c41-827a-9b352d2cf015','01145907-4c06-5f90-bd59-14a940f434a5','Will, Be Going To, Present Continuous (Future)',0,'LESSON',70,$j$[{"type": "rule", "text": "Will is used to express on-the-spot decisions and to make predictions based on what we think or imagine."}, {"type": "examples", "items": ["I'm hungry. I'll make a sandwich.", "One day he'll be a famous football player."]}, {"type": "rule", "text": "Be going to is used to talk about future plans and intentions, and to make predictions based on what we see or know."}, {"type": "examples", "items": ["He is going to spend his holidays in France this year.", "Look at those dark clouds! It is going to rain."]}, {"type": "rule", "text": "The present continuous is used to talk about fixed arrangements in the near future."}, {"type": "examples", "items": ["They're leaving for Frankfurt in an hour."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('149c573b-0bf2-5c06-be1b-f41879af80b6','1af85fad-66d1-5c41-827a-9b352d2cf015',0,'FILL_BLANK','Раскройте скобки, употребив be going to или will.',$j${"items": [{"before": "Look at that boy climbing the tree! Oh no! He", "after": "! [fall]"}, {"before": "Do you have plans for tonight? Yes, I", "after": "at the new Italian restaurant in town. [eat]"}, {"before": "I can't hear the radio. I", "after": "the volume. [turn up]"}, {"before": "Mark is very good at drawing. Yes. I think he", "after": "a great artist one day. [become]"}, {"before": "It's hot in here. Just a minute! I", "after": "the window. [open]"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('149c573b-0bf2-5c06-be1b-f41879af80b6',$j${"items": [{"accept": ["is going to fall", "'s going to fall"]}, {"accept": ["am going to eat", "'m going to eat"]}, {"accept": ["will turn up", "'ll turn up"]}, {"accept": ["will become", "'ll become"]}, {"accept": ["will open", "'ll open"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f6f97c50-16f9-5e19-a258-4a6527467fb4','1af85fad-66d1-5c41-827a-9b352d2cf015',1,'FILL_BLANK','Раскройте скобки, употребив future simple, be going to или present continuous.',$j${"items": [{"before": "It's freezing cold. It", "after": "tonight. [snow]"}, {"before": "We", "after": "Billy and Joanna at the cinema at 7 o'clock. [meet]"}, {"before": "It's Peter's birthday today. I", "after": "him a CD. [buy]"}, {"before": "Look out! You", "after": "! [fall]"}, {"before": "Now that I've got the money, I", "after": "a new car. [buy]"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f6f97c50-16f9-5e19-a258-4a6527467fb4',$j${"items": [{"accept": ["is going to snow", "'s going to snow"]}, {"accept": ["are meeting", "'re meeting"]}, {"accept": ["am going to buy", "'m going to buy"]}, {"accept": ["are going to fall", "'re going to fall"]}, {"accept": ["am going to buy", "'m going to buy"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7217c796-3610-5c47-a0b6-b0b9de9f472b','1af85fad-66d1-5c41-827a-9b352d2cf015',2,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "We haven't got any bread. I", "after": "and buy some.", "options": [{"id": "o1", "label": "am going"}, {"id": "o2", "label": "go to"}, {"id": "o3", "label": "will go"}]}, {"before": "Philip", "after": "a meeting with his boss in an hour.", "options": [{"id": "o1", "label": "going to have"}, {"id": "o2", "label": "is having"}, {"id": "o3", "label": "has"}]}, {"before": "I think Ollie", "after": "a famous actor one day.", "options": [{"id": "o1", "label": "will be"}, {"id": "o2", "label": "is being"}, {"id": "o3", "label": "going to be"}]}, {"before": "Now that Julie has a job, she", "after": "her own flat.", "options": [{"id": "o1", "label": "is buying"}, {"id": "o2", "label": "buys"}, {"id": "o3", "label": "is going to buy"}]}]}$j$::jsonb,10);
