INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('89707e70-a1ff-54af-9ac9-0ac232a0d2cf','a0000000-0000-4000-8000-0000000000a2','Блок 43. The Infinitive (To-infinitive and Bare Infinitive)',43,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('07f2fae4-9751-5792-952c-68dacbb76f5d','89707e70-a1ff-54af-9ac9-0ac232a0d2cf','The Infinitive (To-infinitive and Bare Infinitive)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the to-infinitive after certain verbs (advise, agree, decide, expect, hope, manage, offer, promise, refuse, seem, want), after be + adjective, after too and enough, and to express purpose."}, {"type": "examples", "items": ["He decided to travel abroad.", "I'm sorry to tell you you failed the exam.", "We're too tired to go out tonight.", "Ben went to the supermarket to buy some milk."]}, {"type": "rule", "text": "We use the bare infinitive (without to) after modal verbs and after the verbs let and make."}, {"type": "examples", "items": ["She can do it.", "Her parents didn't let her go out.", "Can you make her stop?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('dd9350b5-0f53-5832-b3b7-5d49259a46bd','07f2fae4-9751-5792-952c-68dacbb76f5d',0,'FILL_BLANK','Заполните пропуски глаголами из списка в правильной форме (to-infinitive или bare infinitive): agree, stay, cross, get, pay, make, buy, help, drive, go.',$j${"items": [{"before": "They advised us", "after": "the fine."}, {"before": "It would be nice", "after": "to the beach today."}, {"before": "You should", "after": "with the housework!"}, {"before": "I don't remember how", "after": "there."}, {"before": "She promised not", "after": "the road alone."}, {"before": "I want to know how", "after": "ice cream."}, {"before": "It's too expensive", "after": "a ticket for the festival."}, {"before": "I would like the children", "after": "over tonight."}, {"before": "She wants to learn how", "after": "a car."}, {"before": "I don't think she will", "after": "to help us."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('dd9350b5-0f53-5832-b3b7-5d49259a46bd',$j${"items": [{"accept": ["to pay"]}, {"accept": ["to go"]}, {"accept": ["help"]}, {"accept": ["to get"]}, {"accept": ["to cross"]}, {"accept": ["to make"]}, {"accept": ["to buy"]}, {"accept": ["to stay"]}, {"accept": ["to drive"]}, {"accept": ["agree"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('023d708f-0cf4-5188-87b3-c38e1a11e1e8','07f2fae4-9751-5792-952c-68dacbb76f5d',1,'FILL_BLANK','Раскройте скобки, употребив глагол в форме to-infinitive или bare infinitive.',$j${"items": [{"before": "What would you like", "after": "for dessert? [have]"}, {"before": "I've always wanted", "after": "pannacotta. [try]"}, {"before": "I don't know how", "after": "an email. [send]"}, {"before": "I can", "after": "you. [show]"}, {"before": "Thanks, but I'm too tired", "after": "out tonight. [go]"}, {"before": "Can you", "after": "talking? I can't concentrate. [stop]"}, {"before": "Her parents made her", "after": "in. [stay]"}, {"before": "Jane was happy", "after": "her exams. [pass]"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('023d708f-0cf4-5188-87b3-c38e1a11e1e8',$j${"items": [{"accept": ["to have"]}, {"accept": ["to try"]}, {"accept": ["to send"]}, {"accept": ["show"]}, {"accept": ["to go"]}, {"accept": ["stop"]}, {"accept": ["stay"]}, {"accept": ["to pass"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('23225e3c-8376-5740-bc59-c863e030fbc0','07f2fae4-9751-5792-952c-68dacbb76f5d',2,'FILL_BLANK','Раскройте скобки, употребив to-infinitive или bare infinitive.',$j${"items": [{"before": "What shall we", "after": "this Saturday? [do]"}, {"before": "Let's", "after": "to the beach. [go]"}, {"before": "Did you ask Tom", "after": "you Tony's phone number? [give]"}, {"before": "Do you expect", "after": "abroad this summer? [travel]"}, {"before": "No, we may", "after": "our summer holidays in our cottage. [spend]"}]}$j$::jsonb,10);
