INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4a6e3ef6-ede4-5e08-a181-dd92f6dccf87','07f2fae4-9751-5792-952c-68dacbb76f5d',3,'FILL_BLANK','Раскройте скобки, употребив правильную форму инфинитива.',$j${"items": [{"before": "I hope that I will be able", "after": "to the party. [come]"}, {"before": "I need", "after": "my parents for permission. [ask]"}, {"before": "But I think they will", "after": "me. [let]"}]}$j$::jsonb,10);
