INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f28b6a70-e039-53b1-9089-a6f6c0c1a002','a0000000-0000-4000-8000-0000000000a2','Блок 44. The -ing Form and the Infinitive',44,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7e2c4e9e-0200-5b0c-9e53-534c4f2d8f16','f28b6a70-e039-53b1-9089-a6f6c0c1a002','The -ing Form and the Infinitive',0,'LESSON',70,$j$[{"type": "rule", "text": "The -ing form is the form of the verb that ends in -ing: being, moving, learning."}, {"type": "text", "text": "We use the -ing form: as a noun; after like, love, dislike, hate, enjoy, prefer; after the verb go when we talk about activities; after start, begin, finish, stop, continue; after prepositions; after avoid, admit, deny, look forward to, mind, regret, spend, suggest; and after phrases like be busy, it's no use, it's no good, it's (not) worth, there's no point in, can't help, can't stand."}, {"type": "text", "text": "We use the to-infinitive (not the -ing form) after would love / would like / would prefer, and after many verbs such as hope, decide, want, promise, advise, agree."}, {"type": "examples", "items": ["Snowboarding is fun.", "Mary loves going to the cinema.", "It started raining an hour ago.", "We're looking forward to going on holiday.", "I would like to go out tonight. BUT I like going out."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6bfa0e58-854f-56ba-a96f-918b92db36aa','7e2c4e9e-0200-5b0c-9e53-534c4f2d8f16',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "She can", "after": "the guitar very well.", "options": [{"id": "o1", "label": "to play"}, {"id": "o2", "label": "play"}, {"id": "o3", "label": "playing"}]}, {"before": "The teacher advised us", "after": "more.", "options": [{"id": "o1", "label": "studying"}, {"id": "o2", "label": "to study"}, {"id": "o3", "label": "study"}]}, {"before": "It is dangerous", "after": "wires with wet hands.", "options": [{"id": "o1", "label": "to touch"}, {"id": "o2", "label": "touching"}, {"id": "o3", "label": "to touching"}]}, {"before": "They decided", "after": "their holiday in New Zealand.", "options": [{"id": "o1", "label": "spending"}, {"id": "o2", "label": "to spend"}, {"id": "o3", "label": "spend"}]}, {"before": "I'd like", "after": "home tonight.", "options": [{"id": "o1", "label": "staying"}, {"id": "o2", "label": "to stay"}, {"id": "o3", "label": "stay"}]}, {"before": "Stella was happy", "after": "her exams.", "options": [{"id": "o1", "label": "to pass"}, {"id": "o2", "label": "passing"}, {"id": "o3", "label": "pass"}]}, {"before": "Do you like", "after": "sports?", "options": [{"id": "o1", "label": "to do"}, {"id": "o2", "label": "doing"}, {"id": "o3", "label": "do"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6bfa0e58-854f-56ba-a96f-918b92db36aa',$j${"items": [{"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('225f8fb0-c8c5-5874-be99-ee86cb657068','7e2c4e9e-0200-5b0c-9e53-534c4f2d8f16',1,'FILL_BLANK','Раскройте скобки, поставив глагол в форму инфинитива или -ing.',$j${"items": [{"before": "Antony hopes", "after": "a doctor. (become)"}, {"before": "He spends a lot of time", "after": "his homework. (do)"}, {"before": "She is looking forward to", "after": "her diploma next month. (receive)"}, {"before": "She hopes", "after": "famous one day. (be)"}, {"before": "She would like", "after": "the world. (travel)"}, {"before": "He can't stand", "after": "to the theatre. (go)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('225f8fb0-c8c5-5874-be99-ee86cb657068',$j${"items": [{"accept": ["to become"]}, {"accept": ["doing"]}, {"accept": ["receiving"]}, {"accept": ["to be"]}, {"accept": ["to travel"]}, {"accept": ["going"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('376068b3-b433-5469-a13d-2e555e5d7fff','a0000000-0000-4000-8000-0000000000a2','Блок 45. Reflexive Pronouns and One/Ones',45,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c5919010-9d2a-5868-b63b-5578e97cf657','376068b3-b433-5469-a13d-2e555e5d7fff','Reflexive Pronouns and One/Ones',0,'LESSON',70,$j$[{"type": "rule", "text": "We use reflexive pronouns (myself, yourself, himself, herself, itself, ourselves, yourselves, themselves) when the subject and the object are the same person, and with the preposition by to mean 'alone' or 'without help'."}, {"type": "text", "text": "We also use them in expressions like enjoy yourself, behave yourself, help yourself, and to emphasise a noun or pronoun."}, {"type": "text", "text": "We use one in the singular and ones in the plural to avoid repeating the noun."}, {"type": "examples", "items": ["They are painting the house themselves.", "He painted the kitchen himself. (without help)", "I want a shirt, a white cotton one.", "I don't like these trousers. I prefer those ones."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('10dec6c3-ab23-58df-9bd6-464f647d965d','c5919010-9d2a-5868-b63b-5578e97cf657',0,'FILL_BLANK','Вставьте правильное возвратное местоимение.',$j${"items": [{"before": "Bye, kids! Enjoy", "after": "!"}, {"before": "She made the dress", "after": "."}, {"before": "John, behave", "after": "or we are leaving."}, {"before": "I like being by", "after": "sometimes."}, {"before": "Bob and Ann painted the house", "after": "."}, {"before": "I don't need help. I can do it", "after": "."}, {"before": "She taught", "after": "how to play the guitar."}, {"before": "Help", "after": "to some cake!"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('10dec6c3-ab23-58df-9bd6-464f647d965d',$j${"items": [{"accept": ["yourselves"]}, {"accept": ["herself"]}, {"accept": ["yourself"]}, {"accept": ["myself"]}, {"accept": ["themselves"]}, {"accept": ["myself"]}, {"accept": ["herself"]}, {"accept": ["yourself"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4a17e51d-e12f-5328-8576-66f366b311cf','c5919010-9d2a-5868-b63b-5578e97cf657',1,'FILL_BLANK','Вставьте one или ones.',$j${"items": [{"before": "These shoes are nice. I like these", "after": "."}, {"before": "Can I have a cake, please? A chocolate", "after": "."}, {"before": "Are these your old trainers or the new", "after": "?"}, {"before": "I haven't got a cap. I'll buy", "after": "."}, {"before": "\"Which is your bag?\" \"The blue", "after": ".\""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4a17e51d-e12f-5328-8576-66f366b311cf',$j${"items": [{"accept": ["ones"]}, {"accept": ["one"]}, {"accept": ["ones"]}, {"accept": ["one"]}, {"accept": ["one"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f3a0a8c4-3dd4-5ce6-82bd-7bbdf2049b69','a0000000-0000-4000-8000-0000000000a2','Блок 46. The Passive',46,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('353b00dd-1d22-50fb-8ceb-57fa62619cb4','f3a0a8c4-3dd4-5ce6-82bd-7bbdf2049b69','The Passive',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the passive with the verb to be + the past participle of the main verb. We use the passive when the action is more important than the person who does it (the agent)."}, {"type": "text", "text": "We can omit the agent when it is unknown, unimportant or obvious. When we want to mention the agent we use by."}, {"type": "examples", "items": ["Feta cheese is produced in Greece.", "The Parthenon was built thousands of years ago.", "'Guernica' was painted by Picasso in 1937."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b94ec862-9ce6-5828-a16b-0c66c126a36e','353b00dd-1d22-50fb-8ceb-57fa62619cb4',0,'FILL_BLANK','Вставьте is, are, was или were.',$j${"items": [{"before": "Visitors", "after": "asked not to touch any statues."}, {"before": "The Parthenon", "after": "built thousands of years ago."}, {"before": "'Guernica'", "after": "painted by Picasso in 1937."}, {"before": "Feta cheese", "after": "produced in Greece."}, {"before": "Many of my relatives", "after": "invited to my wedding last year."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b94ec862-9ce6-5828-a16b-0c66c126a36e',$j${"items": [{"accept": ["are"]}, {"accept": ["was"]}, {"accept": ["was"]}, {"accept": ["is"]}, {"accept": ["were"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('403df321-3c34-5842-a4a1-f80dd5810ea1','353b00dd-1d22-50fb-8ceb-57fa62619cb4',1,'CHOOSE','Выберите правильную форму пассивного залога.',$j${"items": [{"before": "Mitsubishi cars", "after": "in Japan.", "options": [{"id": "o1", "label": "are made"}, {"id": "o2", "label": "were made"}]}, {"before": "The hotel", "after": "built in 1853.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "was"}]}, {"before": "This book", "after": "by Mark Twain.", "options": [{"id": "o1", "label": "wrote"}, {"id": "o2", "label": "was written"}]}, {"before": "Paella", "after": "with seafood.", "options": [{"id": "o1", "label": "is made"}, {"id": "o2", "label": "was made"}]}, {"before": "The village", "after": "by an earthquake.", "options": [{"id": "o1", "label": "is destroyed"}, {"id": "o2", "label": "was destroyed"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('403df321-3c34-5842-a4a1-f80dd5810ea1',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e8625518-51ad-5232-abc6-9fae7137cb8d','a0000000-0000-4000-8000-0000000000a2','Блок 47. Will - Be going to - Present Continuous (Future)',47,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b50daff3-2382-5c45-8da1-ad676b98c4d1','e8625518-51ad-5232-abc6-9fae7137cb8d','Will - Be going to - Present Continuous (Future)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use will for on-the-spot decisions and predictions based on what we think or imagine. We use be going to for future intentions/plans and for predictions based on what we see or know. We use the present continuous for fixed arrangements in the near future."}, {"type": "examples", "items": ["This suitcase is heavy! - Don't worry. I'll carry it for you.", "Do you have any plans for the summer? - Yes, I'm going to spend my holiday in Italy.", "Look at that kite! It's going to hit those electric wires!", "They are flying to Paris next week."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('851d079a-dd46-5298-96a4-c4eb3ebf45b1','b50daff3-2382-5c45-8da1-ad676b98c4d1',0,'FILL_BLANK','Заполните пропуски формой will или be going to.',$j${"items": [{"before": "Why are you wearing those old clothes? - Because I", "after": "wash the car."}, {"before": "This suitcase is very heavy! - Don't worry. I", "after": "carry it for you."}, {"before": "Do you have any plans for the summer? - Yes, I", "after": "spend my holiday in Italy."}, {"before": "Look at that kite! It", "after": "hit those electric wires!"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('851d079a-dd46-5298-96a4-c4eb3ebf45b1',$j${"items": [{"accept": ["am going to wash", "'m going to wash"]}, {"accept": ["will carry", "'ll carry"]}, {"accept": ["am going to spend", "'m going to spend"]}, {"accept": ["is going to hit", "'s going to hit"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('df0206c4-19d4-538a-a9d5-fabd2716a6aa','a0000000-0000-4000-8000-0000000000a2','Блок 48. Present Simple / Present Continuous',48,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('08622298-c384-53cf-a377-a181da8c8fee','df0206c4-19d4-538a-a9d5-fabd2716a6aa','Present Simple / Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for habits, routines and permanent situations. We use the present continuous for actions happening now or around the moment of speaking, and for temporary situations."}, {"type": "examples", "items": ["In the evenings, Ann helps her mum with the housework.", "The children are playing in the garden now.", "Sam is studying hard these days."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0fe0c1b5-ef95-5f8f-bc2a-3e81ed81c3a9','08622298-c384-53cf-a377-a181da8c8fee',0,'FILL_BLANK','Раскройте скобки, поставив глагол в Present Simple или Present Continuous.',$j${"items": [{"before": "What", "after": "at the weekend? (you/do)"}, {"before": "She", "after": "in Moscow. (live)"}, {"before": "What", "after": "at? (you/look)"}, {"before": "In the evenings, Ann", "after": "her mum with the housework. (help)"}, {"before": "The museum", "after": "at eight in the evening. (close)"}, {"before": "Sam", "after": "hard these days. (study)"}, {"before": "", "after": "a paper every day? (your dad/read)"}, {"before": "Jim", "after": "the bus to school at 7:30 in the morning. (catch)"}, {"before": "The children", "after": "in the garden now. (play)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0fe0c1b5-ef95-5f8f-bc2a-3e81ed81c3a9',$j${"items": [{"accept": ["do you do"]}, {"accept": ["lives"]}, {"accept": ["are you looking"]}, {"accept": ["helps"]}, {"accept": ["closes"]}, {"accept": ["is studying", "'s studying"]}, {"accept": ["Does your dad read", "does your dad read"]}, {"accept": ["catches"]}, {"accept": ["are playing", "'re playing"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d43a0647-e6a6-54ab-a4c4-5e002b09d10f','a0000000-0000-4000-8000-0000000000a2','Блок 49. Past Simple / Past Continuous',49,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('0e382d94-a225-5361-bb11-846a29c5a674','d43a0647-e6a6-54ab-a4c4-5e002b09d10f','Past Simple / Past Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the past simple for completed actions in the past. We use the past continuous for an action that was in progress at a certain time in the past, or for a longer action interrupted by a shorter one."}, {"type": "examples", "items": ["I was singing while Roger was playing the guitar.", "He had a shower, then he left for work.", "While my mum was sunbathing, my dad took my brother out in his boat."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('04e96ba6-6f2e-5472-90f2-7f76d4bffd93','0e382d94-a225-5361-bb11-846a29c5a674',0,'FILL_BLANK','Раскройте скобки, поставив глагол в Past Simple или Past Continuous.',$j${"items": [{"before": "It was a lovely day and the sun", "after": ". (shine)"}, {"before": "Some children", "after": "sandcastles. (make)"}, {"before": "Others", "after": ". (swim)"}, {"before": "While my mum", "after": ", my dad took us out in his boat. (sunbathe)"}, {"before": "I", "after": "a big fish! (catch)"}, {"before": "My mum was very surprised when I", "after": "it to her. (show)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('04e96ba6-6f2e-5472-90f2-7f76d4bffd93',$j${"items": [{"accept": ["was shining"]}, {"accept": ["were making"]}, {"accept": ["were swimming"]}, {"accept": ["was sunbathing"]}, {"accept": ["caught"]}, {"accept": ["showed"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1dcc5d7d-5d6b-5f9d-9295-f210bba7bc03','a0000000-0000-4000-8000-0000000000a2','Блок 50. Conditionals',50,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a0736cbd-556b-5c46-aaf3-51f4901b6640','1dcc5d7d-5d6b-5f9d-9295-f210bba7bc03','Conditionals',0,'LESSON',70,$j$[{"type": "rule", "text": "In the first conditional we use: if + present simple, will + infinitive (a real/likely situation). In the second conditional we use: if + past simple, would + infinitive (an unlikely or imaginary situation)."}, {"type": "text", "text": "Unless means 'if not'. We use it instead of if ... not."}, {"type": "examples", "items": ["If it rains, the match will be cancelled.", "If I were you, I'd tell her the truth.", "We can't play golf unless it stops raining."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('74974e1c-2e67-5dd6-988e-08655060dd31','a0736cbd-556b-5c46-aaf3-51f4901b6640',0,'FILL_BLANK','Вставьте if или unless.',$j${"items": [{"before": "We can't play golf", "after": "it stops raining."}, {"before": "", "after": "they beat this team, they will win the tournament."}, {"before": "You can't go skydiving", "after": "you're afraid of heights."}, {"before": "", "after": "it rains, the match will be cancelled."}, {"before": "", "after": "you're over 18, you can't enter the competition."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('74974e1c-2e67-5dd6-988e-08655060dd31',$j${"items": [{"accept": ["unless"]}, {"accept": ["If", "if"]}, {"accept": ["if"]}, {"accept": ["If", "if"]}, {"accept": ["Unless", "unless"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2262e207-a09d-5d54-a98d-f6ffc5b9d57f','a0736cbd-556b-5c46-aaf3-51f4901b6640',1,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "If it", "after": ", the children will make a snowman.", "options": [{"id": "o1", "label": "snows"}, {"id": "o2", "label": "will snow"}, {"id": "o3", "label": "is snowing"}]}, {"before": "If I", "after": "you, I'd tell her about it.", "options": [{"id": "o1", "label": "am"}, {"id": "o2", "label": "have been"}, {"id": "o3", "label": "were"}]}, {"before": "If we had more time, we", "after": "the Prado Museum.", "options": [{"id": "o1", "label": "would visit"}, {"id": "o2", "label": "will visit"}, {"id": "o3", "label": "visited"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2262e207-a09d-5d54-a98d-f6ffc5b9d57f',$j${"items": [{"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('8cbfa03f-1bec-5bd7-94b5-bc2177f0ef33','a0000000-0000-4000-8000-0000000000a2','Блок 51. Question Tags',51,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('bc22bd7c-fbc8-54a2-a249-89f603b47bba','8cbfa03f-1bec-5bd7-94b5-bc2177f0ef33','Question Tags',0,'LESSON',70,$j$[{"type": "rule", "text": "Question tags are short questions at the end of a statement. An affirmative statement takes a negative tag; a negative statement takes an affirmative tag. We use the same auxiliary as in the statement; with present/past simple we use do/does/did."}, {"type": "text", "text": "After Let's ... the tag is shall we? A statement with a negative word (never) is treated as negative."}, {"type": "examples", "items": ["He isn't coming, is he?", "They left yesterday, didn't they?", "Let's go out, shall we?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c10ca074-8bf5-59a3-b98b-325674928a0f','bc22bd7c-fbc8-54a2-a249-89f603b47bba',0,'FILL_BLANK','Вставьте правильный разделительный вопрос (question tag).',$j${"items": [{"before": "Let's go out,", "after": "?"}, {"before": "He isn't coming,", "after": "?"}, {"before": "They left yesterday,", "after": "?"}, {"before": "Stella is never late,", "after": "?"}, {"before": "She comes from Madrid,", "after": "?"}, {"before": "They didn't invite Pete to the party,", "after": "?"}, {"before": "The children are sleeping,", "after": "?"}, {"before": "He walks to work,", "after": "?"}, {"before": "They had a great time at the party,", "after": "?"}, {"before": "He didn't call,", "after": "?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c10ca074-8bf5-59a3-b98b-325674928a0f',$j${"items": [{"accept": ["shall we"]}, {"accept": ["is he"]}, {"accept": ["didn't they"]}, {"accept": ["is she"]}, {"accept": ["doesn't she"]}, {"accept": ["did they"]}, {"accept": ["aren't they"]}, {"accept": ["doesn't he"]}, {"accept": ["didn't they"]}, {"accept": ["did he"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f54320b0-cd0f-56bb-836b-7dd4a6ed9be2','a0000000-0000-4000-8000-0000000000a2','Блок 52. Comparisons',52,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f03a9dfc-476d-544d-96a4-9742dd4e4c9f','f54320b0-cd0f-56bb-836b-7dd4a6ed9be2','Comparisons',0,'LESSON',70,$j$[{"type": "rule", "text": "We use (not) as ... as to compare people/things that are (not) equal. We use the comparative + than to compare two people/things, and the superlative (+ in/of) to compare one with a group."}, {"type": "text", "text": "Too means 'more than enough' (negative). Enough means 'as much as necessary' and goes after adjectives."}, {"type": "examples", "items": ["He's older than his brother.", "She's as tall as her sister.", "She's the best student in the class.", "He's too young to drive a car."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d6ae4f59-82f1-53cc-9a0f-80f8eebd4d6c','f03a9dfc-476d-544d-96a4-9742dd4e4c9f',0,'FILL_BLANK','Вставьте than, of, too, enough, in или as.',$j${"items": [{"before": "He's", "after": "young to drive a car."}, {"before": "She's", "after": "tall as her sister."}, {"before": "He's older", "after": "his brother."}, {"before": "She's the best student", "after": "the class."}, {"before": "Tony is the worst student", "after": "all."}, {"before": "This jacket is", "after": "expensive to buy."}, {"before": "He's old", "after": "to get a driving licence."}, {"before": "She's got longer hair", "after": "me."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d6ae4f59-82f1-53cc-9a0f-80f8eebd4d6c',$j${"items": [{"accept": ["too"]}, {"accept": ["as"]}, {"accept": ["than"]}, {"accept": ["in"]}, {"accept": ["of"]}, {"accept": ["too"]}, {"accept": ["enough"]}, {"accept": ["than"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('91894d52-a868-5f12-ac1e-5e11f4705d19','f03a9dfc-476d-544d-96a4-9742dd4e4c9f',1,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "London is the", "after": "beautiful city in Europe.", "options": [{"id": "o1", "label": "more"}, {"id": "o2", "label": "most"}, {"id": "o3", "label": "much"}]}, {"before": "This book is", "after": "interesting than that one.", "options": [{"id": "o1", "label": "little"}, {"id": "o2", "label": "the least"}, {"id": "o3", "label": "less"}]}, {"before": "Vegetables are healthier", "after": "pizza.", "options": [{"id": "o1", "label": "from"}, {"id": "o2", "label": "by"}, {"id": "o3", "label": "than"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('91894d52-a868-5f12-ac1e-5e11f4705d19',$j${"items": [{"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o3"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('86d47a4e-cece-5896-8083-14cff4bae23b','a0000000-0000-4000-8000-0000000000a2','Блок 53. Present Perfect / Past Simple',53,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('53011ee5-9ac8-5e5a-a32d-97d215bb7cb9','86d47a4e-cece-5896-8083-14cff4bae23b','Present Perfect / Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present perfect for actions that happened at an unstated time in the past, or actions that started in the past and continue up to now (with for/since, just, already, yet, ever, never). We use the past simple for actions completed at a stated time in the past (ago, yesterday, last week)."}, {"type": "examples", "items": ["She has gone to the supermarket. She hasn't come back yet.", "What time did she leave? - An hour ago.", "We went to that new Chinese restaurant last week."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('de21dc6a-5e08-5bc2-9e76-d3b730cbb1c7','53011ee5-9ac8-5e5a-a32d-97d215bb7cb9',0,'FILL_BLANK','Раскройте скобки, поставив глагол в Present Perfect или Past Simple.',$j${"items": [{"before": "She", "after": "to the supermarket. (go)"}, {"before": "She", "after": "back yet. (not/come)"}, {"before": "What time", "after": "? (she/leave)"}, {"before": "Yes, and I", "after": "my room, too. (tidy)"}, {"before": "We", "after": "to that new Chinese restaurant last week. (go)"}, {"before": "I", "after": "you for a long time. (not/see)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('de21dc6a-5e08-5bc2-9e76-d3b730cbb1c7',$j${"items": [{"accept": ["has gone", "'s gone"]}, {"accept": ["hasn't come", "has not come"]}, {"accept": ["did she leave"]}, {"accept": ["have tidied", "'ve tidied"]}, {"accept": ["went"]}, {"accept": ["haven't seen", "have not seen"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('9e61868a-99ab-524a-bd69-f6043888594e','a0000000-0000-4000-8000-0000000000a2','Блок 54. Modal Verbs',54,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4d075c42-4363-5fb3-ac4f-cfb5feb8de1d','9e61868a-99ab-524a-bd69-f6043888594e','Modal Verbs',0,'LESSON',70,$j$[{"type": "rule", "text": "We use must for strong obligation, mustn't for prohibition, and don't have to for absence of obligation. We use should/shouldn't for advice, and can/can't for ability, permission and requests."}, {"type": "examples", "items": ["You must be careful when you cross the street.", "You should see a dentist.", "You mustn't smoke in here.", "It's Sunday, so we don't have to wake up early."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('db815be8-a087-5491-b0ed-29264c4cd1d9','4d075c42-4363-5fb3-ac4f-cfb5feb8de1d',0,'FILL_BLANK','Вставьте подходящий модальный глагол (must, mustn''t, should, shouldn''t, can).',$j${"items": [{"before": "My tooth hurts. - You", "after": "see a dentist."}, {"before": "Jane's angry with me. - I know. You", "after": "lie to her."}, {"before": "You", "after": "use your mobile phone in the classroom. - Sorry, sir."}, {"before": "", "after": "you help me with the dishes?"}, {"before": "Thanks, but I", "after": "finish my homework first."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('db815be8-a087-5491-b0ed-29264c4cd1d9',$j${"items": [{"accept": ["should"]}, {"accept": ["shouldn't", "should not"]}, {"accept": ["mustn't", "must not"]}, {"accept": ["Can", "can"]}, {"accept": ["must"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9f60c6f2-0f66-555b-a84f-a26953c958c7','4d075c42-4363-5fb3-ac4f-cfb5feb8de1d',1,'CHOOSE','Выберите правильный модальный глагол.',$j${"items": [{"before": "You", "after": "be careful when you cross the street.", "options": [{"id": "o1", "label": "couldn't"}, {"id": "o2", "label": "must"}, {"id": "o3", "label": "can't"}]}, {"before": "You", "after": "have a licence to drive a car.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "could"}, {"id": "o3", "label": "can"}]}, {"before": "Does your tooth hurt? You", "after": "see the dentist.", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "should"}, {"id": "o3", "label": "can't"}]}, {"before": "It's Sunday. We", "after": "wake up early tomorrow.", "options": [{"id": "o1", "label": "mustn't"}, {"id": "o2", "label": "don't have to"}, {"id": "o3", "label": "can't"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9f60c6f2-0f66-555b-a84f-a26953c958c7',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4b34e882-ba69-5351-bdef-4c4bbdc0cdae','a0000000-0000-4000-8000-0000000000a2','Блок 55. Relatives (who / which / whose)',55,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('98f8bf92-aac9-56e1-ada7-17e799e408f4','4b34e882-ba69-5351-bdef-4c4bbdc0cdae','Relatives (who / which / whose)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use who for people, which for things/animals, and whose to show possession. Who and which can be replaced by that in defining relative clauses."}, {"type": "examples", "items": ["An architect is someone who designs buildings.", "A pencil is something which you write with.", "The man who is sitting next to Ann is her uncle."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c7acfe7e-5d19-5db7-8fc6-73f28508ebc8','98f8bf92-aac9-56e1-ada7-17e799e408f4',0,'CHOOSE','Выберите правильное относительное местоимение.',$j${"items": [{"before": "I saw a film last night", "after": "was excellent.", "options": [{"id": "o1", "label": "whose"}, {"id": "o2", "label": "who"}, {"id": "o3", "label": "which"}]}, {"before": "The man", "after": "is sitting next to Ann is her uncle.", "options": [{"id": "o1", "label": "which"}, {"id": "o2", "label": "who"}, {"id": "o3", "label": "whose"}]}, {"before": "That's the hotel", "after": "was destroyed in the earthquake.", "options": [{"id": "o1", "label": "which"}, {"id": "o2", "label": "whose"}, {"id": "o3", "label": "who"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c7acfe7e-5d19-5db7-8fc6-73f28508ebc8',$j${"items": [{"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9c7b2385-f598-5c25-b130-9b813f082fad','98f8bf92-aac9-56e1-ada7-17e799e408f4',1,'MATCH_PAIRS','Соедините слово с его определением.',$j${"left": [{"id": "l1", "label": "an architect"}, {"id": "l2", "label": "a nurse"}, {"id": "l3", "label": "a lawyer"}, {"id": "l4", "label": "a vet"}, {"id": "l5", "label": "a scarf"}, {"id": "l6", "label": "a vase"}], "right": [{"id": "r1", "label": "designs buildings"}, {"id": "r2", "label": "looks after patients"}, {"id": "r3", "label": "represents people in court"}, {"id": "r4", "label": "treats sick animals"}, {"id": "r5", "label": "you wear round your neck"}, {"id": "r6", "label": "you put flowers in"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9c7b2385-f598-5c25-b130-9b813f082fad',$j${"pairs": [{"l": "l1", "r": "r1"}, {"l": "l2", "r": "r2"}, {"l": "l3", "r": "r3"}, {"l": "l4", "r": "r4"}, {"l": "l5", "r": "r5"}, {"l": "l6", "r": "r6"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('92715eb4-5ce1-57b9-a3ce-850635178080','a0000000-0000-4000-8000-0000000000a2','Блок 56. Irregular Verbs',56,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8ca78b2c-6ece-5eb2-b30c-361d6074de46','92715eb4-5ce1-57b9-a3ce-850635178080','Irregular Verbs',0,'LESSON',70,$j$[{"type": "rule", "text": "Irregular verbs do not form the past simple and past participle by adding -ed. You have to learn each form (infinitive - past simple - past participle)."}, {"type": "examples", "items": ["go - went - gone", "see - saw - seen", "write - wrote - written", "take - took - taken"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8dd7f61d-4d36-5efa-aae3-27708889e5bd','8ca78b2c-6ece-5eb2-b30c-361d6074de46',0,'SHORT_TEXT','Напишите Past Simple глагола ''go''.',$j${"question": "Past simple of 'go'?"}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8dd7f61d-4d36-5efa-aae3-27708889e5bd',$j${"accept": ["went"]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fbb6b03f-bc63-5650-8356-186c5e3c3de3','8ca78b2c-6ece-5eb2-b30c-361d6074de46',1,'SHORT_TEXT','Напишите Past Participle (третью форму) глагола ''write''.',$j${"question": "Past participle of 'write'?"}$j$::jsonb,10);
